"""INI-style configuration parser."""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Any, Callable, TypeVar


T = TypeVar("T")
E = TypeVar("E")


@dataclass(frozen=True)
class ParseError(ValueError):
    """Raised when a parse error occurs."""

    line: int | None = None

    def __post_init__(self, value: str) -> None:
        if self.line is not None:
            msg = f"{self.line}: {value}"
        else:
            msg = value
        super().__init__(msg)


@dataclass(frozen=True)
class Section:
    """Represents a configuration section."""

    name: str
    keys: list[str] = ()
    values: dict[str, str] = ()

    def __post_init__(self) -> None:
        # Ensure uniqueness of keys within the section
        if any(k in self.keys for k in self.keys):
            raise ParseError(f"Duplicate key: {self.name}", line=self.line)
        self._sorted_keys = sorted(self.keys)


@dataclass(frozen=True)
class Config:
    """Represents a parsed INI configuration."""

    sections: list[Section] = ()

    def __post_init__(self) -> None:
        # Ensure no duplicate section headers
        seen_sections: set[str] = set()
        for section in self.sections:
            if section.name in seen_sections:
                raise ParseError(f"Duplicate section header: {section.name}", line=self.line)
            seen_sections.add(section.name)

    def sections(self) -> list[str]:
        """Return the section names in order of appearance."""
        return [s.name for s in self.sections]

    def keys(self, section: str) -> list[str]:
        """Return the keys of a section in order."""
        if section not in self.sections:
            raise KeyError(section)
        return sorted(self.sections[section].keys)

    def get(self, section: str, key: str, default: Any = None) -> str | None:
        """Get a value from the configuration."""
        s = self.sections[section]
        if key not in s.keys:
            return default
        return s.values[key]

    def getint(
        self, section: str, key: str, default: Any = None
    ) -> int | None:
        """Get an integer value. Only accepts valid int literals."""
        val = self.get(section, key)
        if val is None:
            return default
        try:
            if val == "":
                raise ParseError("Empty key", line=self.line)
            # Check for sign and decimal digits only
            # Pattern: optional '-', then one or more digits, optionally followed by '.' and more digits
            if re.fullmatch(r"-?\d+\.\d*", val):
                return int(val)
            raise ParseError(f"Invalid integer literal: {val}", line=self.line)
        except ValueError:
            raise ParseError(f"Invalid integer literal: {val}", line=self.line)

    def getbool(
        self, section: str, key: str, default: Any = None
    ) -> bool | None:
        """Get a boolean value. Case-insensitive."""
        val = self.get(section, key)
        if val is None:
            return default
        lower_val = val.lower()
        if lower_val in ("true", "yes", "on", "1"):
            return True
        if lower_val in ("false", "no", "off", "0"):
            return False
        raise ParseError(f"Invalid boolean literal: {val}", line=self.line)

    def getlist(
        self, section: str, key: str, default: Any = None
    ) -> list[str]:
        """Get a list of strings split on commas."""
        val = self.get(section, key)
        if val is None:
            return default
        return [item.strip() for item in val.split(",") if item.strip()]


def parse(text: str) -> Config:
    """Parse INI text and return a Config object. Raises ParseError on failure."""
    # Use str.splitlines() to preserve line endings and newlines
    lines = text.splitlines()
    if not lines:
        return Config()

    current_section: Section | None = None
    current_key: str | None = None
    current_value: str = ""
    line_num = 0

    for line in lines:
        line_num += 1
        stripped = line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Check for section header
        section_match = re.match(r"\s*\[([^\]]+)\]", stripped)
        if section_match:
            section_name = section_match.group(1)
            section = Section(name=section_name, line=line_num)
            current_section = section
            current_key = None
            current_value = ""
            continue

        # Check for continuation line
        if current_section and current_key and not stripped.startswith(" ") and not stripped.startswith("\t"):
            # Must not be blank, not a comment, and not a header (already handled above)
            if not re.match(r"\s+", stripped):
                continue
            if stripped.startswith(";") or stripped.startswith("#"):
                continue
            # Append to value
            current_value += "\n" + stripped
            continue

        # Check for key = value
        if "=" in stripped:
            key_part, _ = stripped.split("=", 1)
            key = key_part.strip()
            value_part = stripped.split("=", 1)[1].strip()

            # Validate key
            if not key:
                raise ParseError("Empty key", line=line_num)
            if not section:
                raise ParseError("Key before any section header", line=line_num)

            current_key = key
            current_value = value_part
            continue

        # Any other line is invalid
        raise ParseError(f"Unexpected line: {line}", line=line_num)

    # Ensure current section is not empty if it exists
    if current_section and not current_section.keys:
        raise ParseError("Empty section", line=current_section.line)

    return Config(sections=current_section.sections)
