import re
from datetime import datetime


class CronError(Exception):
    """Base exception for cron parsing errors."""
    pass


class RangeError(CronError):
    """Raised when a range is invalid (A > B)."""
    pass


class StepError(CronError):
    """Raised when a step is not a positive integer."""
    pass


class ValueError(CronError):
    """Raised for various input validation errors."""
    pass


def _is_monthly_field(field: str) -> bool:
    """Check if the cron field is monthly (matches any month)."""
    return field.startswith('*') or field.startswith('A') and field.endswith('M')


def _is_daily_field(field: str) -> bool:
    """Check if the cron field is daily (matches any day of month)."""
    return field.startswith('*') or field.startswith('A') and field.endswith('D')


def _is_weekly_field(field: str) -> bool:
    """Check if the cron field is weekly (matches any day of week)."""
    return field.startswith('*') or field.startswith('A') and field.endswith('W')


def _parse_step(val: str) -> int:
    """Parse a step value like '*/10' or '15/10' into a positive integer."""
    val = val.strip()
    if '/' not in val:
        return 1
    parts = val.split('/')
    if len(parts) != 2:
        raise ValueError(f"Invalid step format: {val}")
    step = _parse_step(parts[0])
    if step <= 0:
        raise StepError(f"Step value must be positive: {val}")
    return step


def _parse_field(field: str) -> list[str]:
    """Parse a cron field into a list of values."""
    field = field.strip()
    values = []

    # Split by comma
    parts = field.split(',')
    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError("Empty field item")

        if not part:
            raise ValueError("Empty item")

        if part.startswith('*'):
            if not _is_monthly_field(part):
                raise ValueError(f"Month field cannot contain '*': {part}")
            values.extend(range(1, 13))
        elif part.startswith('A'):
            end = part[2:].strip()
            if not end:
                raise ValueError(f"Invalid range start: {part}")
            if end.startswith('*'):
                raise ValueError(f"Invalid range end: {end}")
            if end.startswith('M'):
                raise ValueError("Range end cannot be month")
            if not end.startswith('D'):
                raise ValueError(f"Invalid range end: {end}")
            end_val = int(end[1:])
            if end_val < 1 or end_val > 12:
                raise ValueError(f"Range end out of range: {end_val}")
            if _is_monthly_field(part):
                for v in range(end_val - 1, 13, 1):
                    values.append(v)
            else:
                values.append(end_val)
        elif part.startswith('B'):
            start = part[2:].strip()
            if not start:
                raise ValueError(f"Invalid range start: {part}")
            if start.startswith('A'):
                raise ValueError("Invalid range start: A")
            if start.startswith('B'):
                raise ValueError("Invalid range start: B")
            start_val = int(start[1:])
            if start_val < 1:
                raise ValueError(f"Range start out of range: {start_val}")
            if _is_monthly_field(part):
                for v in range(start_val, 13, 1):
                    values.append(v)
            else:
                values.append(start_val)
        elif part.startswith('S'):
            if '/' not in part:
                raise ValueError(f"Step required: {part}")
            step = _parse_step(part[1:])
            if step <= 0:
                raise StepError(f"Step value must be positive: {part}")
            if _is_monthly_field(part):
                for v in range(1, 13, step):
                    values.append(v)
            else:
                for v in range(1, 32, step):
                    values.append(v)
        elif '/' in part:
            raise ValueError(f"Step required: {part}")
        else:
            raise ValueError(f"Unknown item: {part}")

    return values


def _get_day_of_month_days(field: str) -> list[int]:
    """Get the set of valid days of month for a given field."""
    field = field.strip()
    if field.startswith('*'):
        return list(range(1, 32))
    elif field.startswith('A') and field.endswith('D'):
        start = int(field[2])
        end = int(field[3:-1])
        if start > end:
            raise RangeError(f"Range A-B: {start} > {end}")
        return list(range(start, end + 1))
    else:
        # Single value
        return [int(field)]


def _get_day_of_week_days(field: str) -> list[int]:
    """Get the set of valid days of week for a given field."""
    field = field.strip()
    if field.startswith('*'):
        return list(range(0, 8))
    elif field.startswith('A') and field.endswith('W'):
        start = int(field[2])
        end = int(field[3:-1])
        if start > end:
            raise RangeError(f"Range A-B: {start} > {end}")
        return list(range(start, end + 1))
    else:
        # Single value
        return [int(field)]


def _combine_days(field1: str, field2: str) -> set[int]:
    """Combine days of month and day of week as per Vixie cron logic."""
    dm_days = _get_day_of_month_days(field1)
    dw_days = _get_day_of_week_days(field2)

    # If either field is '*', it restricts to the other's days
    if field1.startswith('*') or field2.startswith('*'):
        return set(dw_days)

    # If both are restricted, intersection is required
    return set(dm_days) & set(dw_days)


def _matches_day(d: int, field1: str, field2: str) -> bool:
    """Check if a day of month/day of week matches a field."""
    if field1.startswith('*') or field2.startswith('*'):
        return False
    if d in _get_day_of_month_days(field1) and d in _get_day_of_week_days(field2):
        return True
    return False


def next_run(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Calculate the next time a cron expression fires after the given time.

    Args:
        expr: Five-field cron expression.
        after: Naive datetime, the time to start checking from.

    Returns:
        The earliest time strictly later than 'after' that matches the cron expression.

    Raises:
        ValueError: If the expression is malformed, invalid, or has no matches.
    """
    # Parse the expression
    fields = _parse_field(expr)

    # Validate field counts
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_fields = _parse_field(fields[0])
    hour_fields = _parse_field(fields[1])
    dm_fields = _parse_field(fields[2])
    month_fields = _parse_field(fields[3])
    dw_fields = _parse_field(fields[4])

    # Validate ranges (A-B where A > B is invalid)
    for i, fields_list in enumerate([minute_fields, hour_fields, dm_fields, month_fields, dw_fields]):
        for f in fields_list:
            if 'B' in f:
                # A-B format
                parts = f.split('-')
                if len(parts) != 2:
                    raise ValueError(f"Invalid range in field {i}: {f}")
                a, b = int(parts[0]), int(parts[1])
                if a > b:
                    raise RangeError(f"Range {f} has A ({a}) > B ({b})")

    # Validate steps
    for i, fields_list in enumerate([minute_fields, hour_fields, dm_fields, month_fields, dw_fields]):
        for f in fields_list:
            if 'S' in f:
                step = _parse_step(f)
                if step <= 0:
                    raise StepError(f"Step in field {i} must be positive")

    # Validate month fields
    for i, fields_list in enumerate([minute_fields, hour_fields, month_fields, month_fields]):
        for f in fields_list:
            if not _is_monthly_field(f):
                raise ValueError(f"Month field cannot contain '*': {f}")

    # Validate day fields
    for i, fields_list in enumerate([dm_fields, dw_fields]):
        for f in fields_list:
            if not _is_daily_field(f):
                raise ValueError(f"Day field cannot contain '*': {f}")

    # Determine valid days of month and day of week
    dm_set = _combine_days(dm_fields, dw_fields)
    dm_set = set(dm_set) & set(range(1, 32))  # Ensure within 1-31
    dw_set = _combine_days(minute_fields, dw_fields)

    # Check if the earliest possible match exists
    if not dm_set or not dw_set:
        raise ValueError("No day matches exist for the given expression")

    # Find the next valid time
    current = after.replace(second=0, microsecond=0)

    while current < datetime.min.replace(second=0, microsecond=0):
        # Check if current time matches the cron expression
        if _matches_day(current.day, minute_fields[0], dw_fields[0]) and \
           _matches_day(current.day, minute_fields[1], dw_fields[1]) and \
           _matches_day(current.day, dm_fields[0], dw_fields[2]) and \
           _matches_day(current.day, month_fields[0], dw_fields[3]) and \
           _matches_day(current.day, dw_fields[4], dw_fields[0]):

            return current

        current += datetime.timedelta(days=1)

    raise ValueError("No match found for the given expression and after time")
