from __future__ import annotations
import re
from collections.abc import Mapping, MutableMapping
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

from typing_extensions import LookupError, Type


class PathError(LookupError):
    path: str

    def __init__(self, path: str, **kwargs: Any) -> None:
        self.path = path
        super().__init__(f"Path {path!r}: {str(kwargs).strip()!r}")

    def __str__(self) -> str:
        return f"{self.path!r}"


# Wildcard constant
WILDCARD = object()


def parse(path: str) -> List[Union[str, int, WILDCARD]]:
    """Parse a path string into a list of segments: names (str), indices (int), and wildcards (WILDCARD)."""
    if not path:
        raise PathError("Empty path")

    segments: List[Union[str, int, WILDCARD]] = []
    current_path: str = ""

    i = 0
    while i < len(path):
        c = path[i]

        if c == '[':
            # Look for matching quote
            start_quote = i
            j = i + 1
            while j < len(path):
                if path[j] == '"':
                    # Check for escaped characters inside the quote
                    if j + 1 < len(path) and path[j + 1] == '\\':
                        j += 2
                        continue
                    break
                elif path[j] == '\\' and j + 1 < len(path):
                    # Skip escaped character if any
                    j += 1
                elif path[j] == '"':
                    break
                j += 1

            if j >= len(path):
                raise PathError(f"Unbalanced quotes: {start_quote}:{path[start_quote:]}")

            quoted_key = path[start_quote:j + 1]
            segments.append(quoted_key)

            # Handle negative indices
            if j + 1 < len(path) and path[j + 1] == '-':
                # Extract the number
                start = j + 2
                end = -1
                while end >= 0 and path[end] != '-':
                    end -= 1
                if end < start:
                    raise PathError(f"Invalid integer: {path[start:end+1]}")

                number_str = path[end + 1 : j]
                if not number_str:
                    raise PathError(f"Missing number: {path[start+j+1:]}")

                segments.append(int(number_str))
                j += 1

            i = j + 1
            continue

        if c == '"':
            # Single quote (escaped)
            if i + 1 < len(path) and path[i + 1] == '\\':
                i += 2
            else:
                i += 1
            continue

        if c == '.':
            # Dots must follow a name, not a bracket
            if segments:
                raise PathError("Dots before brackets: " + path[i:])
                break
            segments.append('')
            i += 1
            continue

        if c.isdigit():
            while i < len(path) and path[i].isdigit():
                i += 1
            segments.append(int(path[i - 1 : i]))
            i += 1
            continue

        if c == '[':
            segments.append(WILDCARD)
            i += 1
            continue

        if c == ']' or c == '}':
            raise PathError(f"Unclosed bracket: {path[i:]!r}")
            continue

        if c == '"':
            raise PathError(f"Unquoted name after segment: {path[i:]!r}")
            continue

        if c == 'a':
            raise PathError("Invalid character: " + path[i:])
            continue

        raise PathError(f"Invalid character: {path[i:]!r}")

    return segments
