def _get_nested_value(obj: Any, path_segments: List[Union[str, int, WILDCARD]]) -> Any:
    """
    Recursively get a value from obj using path_segments.
    Returns a list of values if there is at least one wildcard.
    Returns None if the path is completely missing or invalid for a value lookup.
    """
    if not path_segments:
        return None

    result: Any = []

    for segment in path_segments:
        if segment == WILDCARD:
            # Find the index of the wildcard
            wildcard_idx = path_segments.index(WILDCARD)
            rest = path_segments[wildcard_idx + 1:]

            # Navigate to the list/tuple/mapping containing the wildcard
            curr = result

            if isinstance(curr, (list, tuple)):
                if len(rest) > 0:
                    if isinstance(curr[0], (list, tuple)):
                        curr = curr[0]
                    else:
                        curr = curr[0]
                else:
                    # No more segments, return the current list/tuple
                    return curr
            elif isinstance(curr, Mapping):
                # Get the first key from the rest of the path
                # We need to match the next segment type (str, int, WILDCARD)
                if len(rest) == 1 and isinstance(rest[0], str):
                    try:
                        key = int(rest[0])
                        curr = curr[key]
                    except (ValueError, TypeError):
                        # If rest[0] is not an int, it must be a key name or a string
                        # In the context of wildcards, we treat the first segment after wildcard as a key
                        # but we need to be careful. The problem says: "matches every element of a list or tuple ... or every value of a mapping"
                        # "Branches where the rest of the path is missing are skipped."
                        # This implies if we have a wildcard, we consume the next non-wildcard segment as a key to descend further.
                        # However, the description says "Branches where the rest of the path is missing are skipped".
                        # Let's assume the path is well-formed enough that we can descend.
                        # Actually, re-reading: "In a list, an index from -len to len - 1 refers to an existing element... index len appends."
                        # This applies to the non-wildcard segments.
                        # For a wildcard, we look at the next segment. If the next segment is a key (str or int), we descend.
                        # If the next segment is a wildcard, we stop (no further descent).
                        # If the next segment is missing, we stop (no further descent).
                        # If the next segment is a number but not an index (e.g. 'key'), we try to get key from list/tuple? No, list/tuples only have integers.
                        # So if we have a wildcard, followed by a string key, and that string key is NOT in the list/tuple, we stop?
                        # The prompt says "matches every value of a mapping (in insertion order)". So if curr is a mapping, we get the first item.
                        # If curr is a list, we get the first item.
                        # If we have a wildcard, followed by a key string, and the list/tuple doesn't have that key, what happens?
                        # "Branches where the rest of the path is missing are skipped."
                        # This likely means if we try to descend but can't find the key, we stop.
                        # But wait, "Branches where the rest of the path is missing are skipped" usually applies when the path is incomplete (e.g. wildcard, then no segments).
                        # Let's assume standard behavior: try to descend. If curr is a mapping, take the first key. If curr is a list, take the first item.
                        # If the key/index is missing, we stop.
