def _set_nested_value(obj: Any, path_segments: List[Union[str, int, WILDCARD]], value: Any) -> None:
    """
    Set a value using path_segments.
    Must have at least one non-wildcard segment.
    Every segment but the last is followed as get does, creating new containers as needed.
    """
    if not path_segments:
        raise PathError("Empty path")

    # Check if there is exactly one wildcard
    wildcard_count = path_segments.count(WILDCARD)
    if wildcard_count > 1:
        raise PathError("Path cannot contain more than one wildcard")

    if wildcard_count > 0:
        raise PathError("Path cannot contain a wildcard")

    # Find the index of the last non-wildcard segment
    last_idx = -1
    for i, seg in enumerate(path_segments):
        if seg != WILDCARD:
            last_idx = i
            break

    if last_idx == -1:
        # No non-wildcard segment found
        raise PathError("Path must have at least one segment")

    # Create the path object up to (but not including) the last segment
    path_obj = _PathImpl(path_segments[:last_idx], obj)
    result = _get_value(path_obj._obj, path_obj._segments[:last_idx])

    if not isinstance(result, (list, tuple)):
        raise PathError(f"Cannot set value at segment {path_segments[last_idx]}: {result} is not a list or tuple")

    # Determine the index for the last segment
    last_segment = path_segments[last_idx]
    if isinstance(last_segment, str):
        raise PathError(f"Cannot use string as index: {last_segment}")
    elif isinstance(last_segment, int):
        # Check range
        if last_segment < 0:
            raise PathError(f"Negative indices not allowed for new lists: {last_segment}")
        if last_segment >= len(result):
            raise PathError(f"Index out of range: {last_segment}")
        result = result[last_segment]
    else:
        raise PathError(f"Cannot use {last_segment} as index: {last_segment} is not an integer")

    # Now set the value
    if last_segment == 0:
        result = [value]
    else:
        result.append(value)

    # Create new list at the last segment if it doesn't exist
    if isinstance(result, list):
        result = result[:last_segment+1] + [value]
