def delete(obj: Any, path: str) -> Any:
    """
    Remove the value at path from its parent dict or list.
    Returns the removed value.
    Raises PathError if the path is empty, contains a wildcard, or parent is not a dict/list.
    Raises PathError if the value is missing.
    """
    if not path:
        raise PathError("Empty path")
    if WILDCARD in parse(path):
        raise PathError("Path contains a wildcard")
    if not isinstance(obj, (dict, list)):
        raise PathError(f"Cannot delete from {type(obj).__name__}")

    path_segments = parse(path)
    if path_segments[0] == WILDCARD:
        raise PathError("Path contains a wildcard")

    # Build the path object
    obj_path = _PathImpl(path_segments, obj, None)
    obj_val = _get_value(obj_path._obj, obj_path._segments)

    if not isinstance(obj_val, (dict, list)):
        raise PathError(f"Cannot delete from {type(obj).__name__} at path {path}")

    if not isinstance(obj_val, Mapping):
        raise PathError(f"Cannot delete a list/tuple from {type(obj).__name__} at path {path}")

    # Check if the value exists
    if obj_val is None:
        raise PathError(f"Key not found: {path}")

    # Navigate to the list/tuple to delete from
    curr = obj_val
    for seg in path_segments[:-1]:
        if isinstance(curr, Mapping):
            if seg not in curr:
                raise PathError(f"Key not found: {path}")
            curr = curr[seg]
        else:
            if isinstance(curr, list):
                if seg < 0:
                    raise PathError(f"Negative indices not allowed for new lists: {seg}")
                if seg >= len(curr):
                    raise PathError(f"Index out of range: {seg}")
                curr = curr[seg]
            else:
                raise PathError(f"Cannot delete from {type(curr).__name__} at path {path}")

    # Delete the value
    del curr

    return obj_val
