    if not isinstance(result, (list, tuple)):
        raise PathError(f"Cannot set value at segment {path_segments[last_idx]}: {result} is not a list or tuple")

    last_segment = path_segments[last_idx]
    if isinstance(last_segment, str):
        raise PathError(f"Cannot use string as index: {last_segment}")
    elif isinstance(last_segment, int):
        if last_segment < 0:
