        if last_segment >= len(result):
            raise PathError(f"Index out of range: {last_segment}")
        result = result[last_segment]
    else:
        raise PathError(f"Cannot use {last_segment} as index: {last_segment} is not an integer")

    if last_segment == 0:
        result = [value]
    else:
        result.append(value)

    if isinstance(result, list):
        result = result[:last_segment+1] + [value]


def get(obj: Any, path: str, default: Optional[Any] = None) -> Optional[Any]:
    path_obj = _PathImpl(path, obj, default)
    return _get_value(path_obj._obj, path_obj._segments)


def set(obj: Any, path: str, value: Any) -> None:
    path_obj = _PathImpl(path, obj)
    _set_nested_value(path_obj._obj, path_obj._segments, value)


def delete(obj: Any, path: str) -> Any:
    return delete(obj, path)
