UNIT_LENGTH_BASE = "m"
UNIT_MASS_BASE = "kg"
UNIT_TIME_BASE = "s"

# Simple length units
LENGTH_UNITS: dict[str, float] = {
    "mm": 0.001,
    "cm": 0.01,
