def parse_unit_name(name: str) -> Dimension:
    """
    Parse a unit name (e.g., 'm', 'm/s', 'kg*m/s^2') into a Dimension.
    Returns DimensionError if invalid.
    """
    if not name:
        raise UnitError("Empty unit name")
    if not name.replace("-", "").isascii():
        raise UnitError("Invalid non-ASCII characters in unit name")
    if name[-1] in "/**":
        raise UnitError("Invalid unit name: trailing /, *, or **")

    parts = name.split("/")
    dimension = Dimension.LENGTH

    for part in parts:
        # Handle optional exponent
        if part.endswith("^"):
            base_part = part[:-1]
            if not base_part:
                raise UnitError("Missing exponent")
            exponent_str = base_part[-1]
            if not exponent_str.isdigit():
                raise UnitError("Invalid exponent")
            exponent = int(exponent_str)
            # Handle negative exponent for base units
            if exponent < 0:
                exponent = -exponent
                dimension = dimension.__neg__()
            continue

        # Simple unit
        if part not in LENGTH_UNITS:
            raise UnitError(f"Unknown length unit: {part}")
        dimension = LENGTH_UNITS[part]
        continue

        # Mass unit
        if part not in MASS_UNITS:
            raise UnitError(f"Unknown mass unit: {part}")
        dimension = MASS_UNITS[part]
        continue

        # Time unit
        if part not in TIME_UNITS:
            raise UnitError(f"Unknown time unit: {part}")
        dimension = TIME_UNITS[part]
        continue

    if dimension == Dimension.LENGTH and name.endswith("/"):
        raise UnitError("Missing unit in composite unit")

    if dimension == Dimension.MASS and name.endswith("/"):
        raise UnitError("Missing unit in composite unit")

    if dimension == Dimension.TIME and name.endswith("/"):
        raise UnitError("Missing unit in composite unit")

    return dimension


