"""Standard 9×9 Sudoku solver and checker with hints and difficulty rating."""

import re
from typing import Optional


def parse(text: str) -> list[list[int]]:
    """
    Parse a text string into a grid of integers.
    """
    normalized = re.sub(r'\s+', ' ', text.strip())
    if normalized.count(' ') != 81:
        raise ValueError(f"Invalid length: expected 81 cells, found {normalized.count(' ')}")

    rows = []
    current_row = []
    i = 0
    while i < len(normalized):
        if normalized[i] == ' ':
            i += 1
            continue
        if not normalized[i].isdigit() and normalized[i] != '.':
            raise ValueError(f"Invalid character at index {i}: '{normalized[i]}'")
        if normalized[i] == '0' or normalized[i] == '.':
            current_row.append(0)
        else:
            current_row.append(int(normalized[i]))
        i += 1
        if i < len(normalized) and normalized[i] == ' ':
            i += 1

    for row in current_row:
        rows.append([int(x) for x in row])

    if len(rows) != 9 or not all(len(row) == 9 for row in rows):
        raise ValueError("Invalid shape: grid must have exactly 9 rows of 9 columns.")
    return rows


def to_string(grid: list[list[int]]) -> str:
    """Convert a grid to a single string."""
    result = ""
    for row in grid:
        result += "".join(str(cell) for cell in row)
    return result


def is_valid(grid: list[list[int]]) -> bool:
    """Check if a grid is valid according to Sudoku rules."""
    rows, cols = 9, 9
    boxes = 3

    for r in range(rows):
        if len(set(grid[r])) != 9:
            return False
    for c in range(cols):
        col = [grid[r][c] for r in range(rows)]
        if len(set(col)) != 9:
            return False
    for box_r in range(0, rows, boxes):
        for box_c in range(0, cols, boxes):
            box = [grid[br][bc] for br in range(boxes) for bc in range(boxes) if br * 3 + bc == box_r * 3 + box_c]
            if len(set(box)) != 9:
                return False
    return True


def solve(grid: list[list[int]]) -> Optional[list[list[int]]]:
    """
    Solve a valid Sudoku grid using backtracking.
    Returns None if invalid or no solution exists (but grid is valid).
    Never modifies the input grid.
    """
    if not is_valid(grid):
        return None

    def is_candidate(r: int, c: int, d: int) -> bool:
        if d in grid[r]: return False
        if d in [grid[r][c] for r in range(9)]: return False
        box_r, box_c = r // 3, c // 3
        if d in [grid[br][bc] for br in range(3) for bc in range(3) if br * 3 + bc == box_r * 3 + box_c]: return False
        return True

    def backtrack() -> Optional[list[list[int]]]:
        found_empty = False
        for r in range(9):
            for c in range(9):
                if grid[r][c] == 0:
                    for d in range(1, 10):
                        if is_candidate(r, c, d):
                            grid[r][c] = d
                            if backtrack():
                                return grid.copy()
                            grid[r][c] = 0
                    found_empty = True
                    break
            if found_empty:
                break
        return None

    solution = backtrack()
    return solution


def count_solutions(grid: list[list[int]], limit: int = 2) -> int:
    """Count solutions, capping at limit."""
    if limit < 1:
        raise ValueError("limit must be at least 1")
    total = 0
    if is_valid(grid):
        def count_all() -> int:
            found_count = 0
            grid_copy = grid.copy()
            def backtrack():
                nonlocal found_count
                for r in range(9):
                    for c in range(9):
                        if grid_copy[r][c] == 0:
                            for d in range(1, 10):
                                if not is_candidate(r, c, d): continue
                                grid_copy[r][c] = d
                                found_count += 1
                                if backtrack():
                                    found_count -= 1
                                grid_copy[r][c] = 0
                            found_count += 1
            backtrack()
            return found_count
        total = min(count_all(), limit)
    return total


def candidates(grid: list[list[int]]) -> list[int]:
    """
    Get candidates for each empty cell.
    Returns a list of (row, col, digit) tuples.
    Raises ValueError if grid is invalid or bad shape.
    """
    if not is_valid(grid):
        raise ValueError("Grid is invalid")
    candidates_list = []
    for r in range(9):
        for c in range(9):
            if grid[r][c] != 0:
                continue
            row_vals = grid[r]
            col_vals = [grid[r][c] for r in range(9)]
            box_vals = [grid[br][bc] for br in range(3) for bc in range(3) if br*3+bc == r*3+c]
            for d in range(1, 10):
                if d not in row_vals and d not in col_vals and d not in box_vals:
                    candidates_list.append((r, c, d))
    return candidates_list


def hint(grid: list[list[int]]) -> Optional[tuple[int, int, int, str]]:
    """
    Return the next logical step: (row, col, digit, reason).
    Orders:
    1. Naked single: first empty cell with exactly 1 candidate in row-major order.
    2. Hidden single: first digit '1'...'9' that is a candidate for exactly one empty cell,
       ordered by units (rows 0-8, cols 0-8, boxes 0-8), then by digit 1-9.

    Returns None if no step exists (e.g., solved or invalid). Raises ValueError if invalid.
    """
    if not is_valid(grid):
        raise ValueError("Grid is invalid")

    def unit_candidates(r: int, c: int, d: int) -> bool:
        """Check if digit d is a candidate for exactly one empty cell in the unit defined by (r,c,d)."""
        unit = [(br, bc, d) for br in range(3) for bc in range(3) if br*3 + bc == r*3 + c]
        count = 0
        for empty_r, empty_c in unit:
            if grid[empty_r][empty_c] == 0:
                count += 1
        return count == 1

    # 1. Naked single
    for r in range(9):
        for c in range(9):
            if grid[r][c] != 0:
                continue
            if len(candidates(grid)) == 1:
                return (r, c, candidates(grid)[0][2], 'naked single')

    # 2. Hidden single
    # Order: rows 0-8, cols 0-8, boxes 0-8
    def unit_order(r: int, c: int) -> int:
        box_r, box_c = r // 3, c // 3
        return box_r * 9 + box_c

    hidden_found = False
    for r in range(9):
        for c in range(9):
            if grid[r][c] != 0:
                continue
            # Iterate through digits 1..9
            for d in range(1, 10):
                if not is_candidate(r, c, d):
                    continue
                if unit_candidates(r, c, d):
                    return (r, c, d, 'hidden single in row')
            # Move to next unit
            if r * 9 + c == 8:
                continue

    return None


def difficulty(grid: list[list[int]]) -> Optional[dict[str, int]]:
    """
    Compute difficulty based on hints.
    Repeatedly applies hint, fills the cell, counts 'naked' and 'hidden' steps.
    Returns {'naked': N, 'hidden': H}.
    Raises ValueError if invalid or bad shape.
    Never modifies the argument.
    """
    if not is_valid(grid):
        raise ValueError("Grid is invalid")

    grid = grid.copy()
    steps = {'naked': 0, 'hidden': 0}

    while True:
        step = hint(grid)
        if step is None:
            # No logical step, but check if grid is complete
            if all(cell != 0 for row in grid for cell in row):
                break
            return None

        row, col, digit, reason = step
        grid[row][col] = digit
        steps[reason] += 1

        # Check if solved
        if all(cell != 0 for row in grid for cell in row):
            break

        # Recalculate candidates because the grid changed
        candidates = candidates(grid)

    return steps
