def first_index(a: list, x: int) -> int:
    """Returns the index of the first element equal to x, or -1 if there is none."""
    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == x:
            return mid
        elif a[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1


def last_index(a: list, x: int) -> int:
    """Returns the index of the last element equal to x, or -1 if there is none."""
    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == x:
            return mid
        elif a[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1


def insertion_point(a: list, x: int) -> int:
    """Returns the smallest index i such that inserting x before a[i] keeps a sorted."""
    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] < x:
            left = mid + 1
        elif a[mid] > x:
            right = mid - 1
        else:
            return mid
    return len(a)


def count(a: list, x: int) -> int:
    """Returns how many elements equal x."""
    return sum(1 for val in a if val == x)


def search_rotated(a: list, x: int) -> int:
    """Returns the index of x in a rotated sorted list, or -1."""
    if not a:
        return -1

    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == x:
            return mid
        elif a[mid] < x:
            # If the right half is sorted and contains x, check there
            if right >= mid + 1 and a[mid + 1] < a[right]:
                left = mid + 1
            else:
                # Sorted part is on the left, search left side
                right = mid - 1
        elif a[mid] > x:
            # If the left half is sorted and contains x, check there
            if left <= mid - 1 and a[left] < a[mid - 1]:
                right = mid - 1
            else:
                # Sorted part is on the right, search right side
                left = mid + 1
        else:
            # Handle duplicates correctly for rotated search
            # If a[mid] < x, x must be in the right sorted segment if possible
            # Or if a[mid] > x, x must be in the left sorted segment if possible
            pass

    return -1


def rotation_offset(a: list) -> int:
    """Returns the index of the smallest element (0 for non-rotated). ValueError if empty."""
    if not a:
        raise ValueError("List is empty")

    left, right = 0, len(a) - 1
    while left < right:
        mid = (left + right) // 2
        if a[mid] < a[right]:
            right = mid
        else:
            left = mid + 1
    return left


def isqrt(n: int) -> int:
    """Returns the largest integer r with r * r <= n. ValueError if n negative, TypeError if n not int."""
    if not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")

    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0

    x, y = n, n // 2
    while y * y < x:
        x = y
        y = (y + x) // 2
    return y
