from __future__ import annotations

from typing import Mapping, Any


class TemplateError(ValueError):
    def __init__(self, position: int = 0) -> None:
        super().__init__(f"Invalid template at position {position}")
        self.position = position


class MissingKey(KeyError):
    def __init__(self, name: str) -> None:
        super().__init__(name)
        self.name = name


def _normalize_name(name: str) -> str:
    # A valid name starts with an ASCII letter or _ followed by ASCII letters, digits or _
    if not name or not (name[0] >= 'a' and name[0] <= 'z' or name[0] == '_'):
        raise TemplateError(name.find("{") + 1)
    if not all(c in "abcdefghijklmnopqrstuvwxyz0123456789_" for c in name):
        raise TemplateError(name.find("{") + 1)
    return name


def _is_literal(text: str) -> bool:
    return "{\\" in text or "}}\\" in text


def render(template: str, values: Mapping[str, Any]) -> str:
    if not template:
        return ""

    position = 0
    result = []
    i = 0

    while i < len(template):
        if template[i] == "{":
            if i + 1 >= len(template):
                raise TemplateError(i)

            # Check for nested literal braces
            if i + 2 < len(template) and _is_literal(template[i + 1:i + 2]):
                result.append(template[i + 1])
                result.append(template[i + 2])
                i += 2
                continue

            # Try to parse a placeholder
            pos = i + 1
            name = ""
            while pos < len(template):
                if template[pos] == "{":
                    raise TemplateError(pos)
                if template[pos] == "}":
                    break
                name += template[pos]
                pos += 1

            if pos >= len(template) or template[pos] != "}":
                raise TemplateError(i)

            # Normalize name
            name = _normalize_name(name)

            if name not in values:
                raise MissingKey(name)

            # Get value
            val = values[name]
            # Ensure value is a string
            if not isinstance(val, str):
                val = str(val)

            result.append(val)

        elif template[i] == "{{":
            result.append("{")
            i += 1
        elif template[i] == "}}":
            result.append("}")
            i += 1
        else:
            result.append(template[i])
            i += 1

    return "".join(result)


def placeholders(template: str) -> list[str]:
    if not template:
        return []

    result = []
    i = 0

    while i < len(template):
        if template[i] == "{":
            # Check for literal {{
            if i + 1 < len(template) and _is_literal(template[i + 1:i + 2]):
                result.append("{")
                i += 1
                continue

            # Check for literal }
            if i + 1 < len(template) and _is_literal(template[i + 1:i + 2]):
                result.append("}")
                i += 1
                continue

            # Try to parse a placeholder
            pos = i + 1
            name = ""
            while pos < len(template):
                if template[pos] == "{":
                    raise TemplateError(pos)
                if template[pos] == "}":
                    break
                name += template[pos]
                pos += 1

            if pos >= len(template) or template[pos] != "}":
                raise TemplateError(i)

            # Normalize name
            name = _normalize_name(name)

            result.append(name)

        else:
            result.append(template[i])
            i += 1

    return result
