import argparse
import sys
from typing import List, Optional

from .model import Task
from .store import TodoStore, StoreError, TaskError

TASK_LIST_LINE_FORMAT = r"<id> \[ \] <title>"
TASK_DONE_LINE_FORMAT = r"<id> \[x\] <title>"
TAG_PATTERN = r"#\w+"  # Matches #tag where tag is word characters

def print_task_line(task: Task, prefix: str = "") -> None:
    line = f"{prefix}{TASK_LIST_LINE_FORMAT}"
    if task.done:
        line = f"{prefix}{TASK_DONE_LINE_FORMAT}"
    else:
        for tag in task.tags:
            tag_line = f" #tag" if tag else ""
            line += f" {tag_line}"
    print(line)


def cmd_add(args: argparse.Namespace) -> int:
    if not args.title:
        print("error: title required", file=sys.stderr)
        return 2

    try:
        task = Task.from_dict({"id": args.id, "title": args.title, "tags": args.tags})
        print(f"added {task.id}")
        return 0
    except TaskError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2


def cmd_list(args: argparse.Namespace) -> int:
    if args.status and not args.status in ("open", "done", "all"):
        print("error: invalid status", file=sys.stderr)
        return 2

    result = []
    for task in TodoStore(args.store).list(status=args.status, tags=args.tags):
        result.append(task)

    if not result:
        return 0

    for task in result:
        print_task_line(task)

    return 0


def cmd_done(args: argparse.Namespace) -> int:
    ids = [int(id_str) for id_str in args.ids]

    missing = set(ids) - set(i.id for i in TodoStore(args.store).list())
    if missing:
        if not missing:
            print("error: no task with id", file=sys.stderr)
            return 1
        missing_ids = sorted(missing)
        print(f"error: no task with id", file=sys.stderr)
        print(f"{missing_ids}", file=sys.stderr)
        return 1

    for id_str in ids:
        try:
            task = TodoStore(args.store).mark_done(int(id_str))
            print(f"done {int(id_str)}")
        except TaskError as e:
            print(f"error: {e}", file=sys.stderr)
            return 2

    return 0


def cmd_remove(args: argparse.Namespace) -> int:
    if not args.id:
        print("error: id required", file=sys.stderr)
        return 2

    task = TodoStore(args.store).remove(args.id)
    print(f"removed {args.id}")
    return 0


def cmd_edit(args: argparse.Namespace) -> int:
    if not args.id:
        print("error: id required", file=sys.stderr)
        return 2

    if not (args.title or args.add_tags or args.remove_tags):
        print("error: must specify --title, --tag, or --untag", file=sys.stderr)
        return 2

    task = TodoStore(args.store).edit(args.id)

    if args.title is not None:
        print(f"edited {args.id}")
    else:
        for tag in args.add_tags:
            print(f"edited {args.id}")
        for tag in args.remove_tags:
            print(f"edited {args.id}")

    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Todo manager")
    parser.add_argument("command", nargs="?", help="Command to run")
    parser.add_argument("--file", default="todo.json", help="Path to the store file")

    subparsers = parser.add_subparsers(dest="command", help="Commands")

    # Add command
    add_parser = subparsers.add_parser("add", help="Add a task")
    add_parser.add_argument("title", help="Task title")
    add_parser.add_argument("--tag", action="append", help="Tag to add")

    # List command
    list_parser = subparsers.add_parser("list", help="List tasks")
    list_parser.add_argument("--status", choices=["open", "done", "all"], default="open", help="Filter by status")
    list_parser.add_argument("--tag", action="append", help="Filter by tags")

    # Done command
    done_parser = subparsers.add_parser("done", help="Mark tasks done")
    done_parser.add_argument("ids", nargs="*", help="Task ids")

    # Remove command
    remove_parser = subparsers.add_parser("remove", help="Remove a task")
    remove_parser.add_argument("id", help="Task id")

    # Edit command
    edit_parser = subparsers.add_parser("edit", help="Edit a task")
    edit_parser.add_argument("id", help="Task id")
    edit_parser.add_argument("--title", help="New title")
    edit_parser.add_argument("--tag", action="append", help="Tag to add")
    edit_parser.add_argument("--untag", action="append", help="Tag to remove")

    args = parser.parse_args(argv)

    if args.command is None:
        parser.print_help()
        return 1

    try:
        if args.command == "add":
            return cmd_add(args)
        elif args.command == "list":
            return cmd_list(args)
        elif args.command == "done":
            return cmd_done(args)
        elif args.command == "remove":
            return cmd_remove(args)
        elif args.command == "edit":
            return cmd_edit(args)
    except (TaskError, ValueError, StoreError) as e:
        print(f"error: {e}", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        return 1

    return 0
