        except Exception as e:
            raise StoreError(f"Failed to open store file: {e}")

        # Validate structure
        if not isinstance(data, dict):
            raise StoreError("Store file must be a JSON object")

        if 'version' not in data:
            raise StoreError("Store file must have 'version' key")
        if data['version'] != 2:
            raise StoreError("Store file must be version 2")

        if 'tasks' not in data:
            raise StoreError("Store file must have 'tasks' key")

        # Parse and validate tasks
        tasks = []
        seen_ids: set[int] = set()
        for task_dict in data['tasks']:
            task = Task.from_dict(task_dict)
            tasks.append(task)

        if len(tasks) != len(data['tasks']):
            raise StoreError("Store file has mismatched number of tasks")

        # Validate IDs order and uniqueness
        for task_dict in data['tasks']:
            if task_dict['id'] in seen_ids:
                raise StoreError(f"Duplicate task ID: {task_dict['id']}")
            if task_dict['id'] < self._next_id:
                raise StoreError(f"Invalid task ID: {task_dict['id']} (must be >= {self._next_id})")
            seen_ids.add(task_dict['id'])

        # Update internal state
        self._tasks = tasks
        self._next_id = max([t.id for t in tasks]) + 1

    @property
    def path(self) -> Path:
        return self.path

    def add(self, title: str, tags=(), priority: str = "normal", due: Optional[date] = None) -> Task:
        task = Task(
            id=self._next_id,
            title=title,
            tags=tags,
            done=False,
            priority=priority,
            due=due
        )
        self._tasks.append(task)
        self._next_id += 1
        return task

    def edit(self, task_id: int, title: Optional[str] = None, add_tags=(), remove_tags=(),
             priority: Optional[str] = None, due: Optional[date] = None,
             clear_due: bool = False) -> Task:
        task = self.get(task_id)

        # Validate title if provided
        if title is not None:
            title = title.strip()
            if not title:
                raise ValueError("Empty title")
            if not re.match(r'^[a-z0-9][a-z0-9_-]*$', title):
                raise ValueError("Invalid title format")

        # Normalize tags
        if add_tags:
            for t in add_tags:
                t = t.strip()
                if not t:
                    raise ValueError("Empty tag")
                if not re.match(r'^[a-z0-9][a-z0-9_-]*$', t):
                    raise ValueError("Invalid tag format")
            task.tags = sorted(set(task.tags + [t for t in add_tags if t]))
        else:
            task.tags = []

        if remove_tags:
            for t in remove_tags:
                if t in task.tags:
                    task.tags.remove(t)

        # Update fields
        if title is not None:
            task.title = title
        if priority is not None:
            task.priority = priority
        if due is not None:
            task.due = due
        if clear_due:
            task.due = None

        return task

    def get(self, task_id: int) -> Task:
        for task in self._tasks:
            if task.id == task_id:
                return task
        raise KeyError(f"Task with id {task_id} not found")

    def list(self, status: str = "open", tags=(), overdue: bool = False,
             today: Optional[date] = None, sort: str = "id") -> list[Task]:
        # Validate status
        if status not in ("open", "done", "all"):
            raise ValueError("Invalid status")

        # Validate overdue and today
        if overdue and today is None:
            raise ValueError("overdue requires today")

        # Determine sorting key based on sort type
        if sort == "priority":
            priority_key = lambda t: {"high": 3, "normal": 2, "low": 1}.get(t.priority, 0)
        elif sort == "due":
            due_key = lambda t: (0 if t.due is None else t.due)
        else:  # sort == "id"
            due_key = None
            priority_key = None

        result = []
        for task in self._tasks:
            # Apply status filter
            if status == "open" and task.done:
                continue
            if status == "done" and not task.done:
                continue
            if status == "all":
                pass

            # Apply tag filter
            task_tags = [t for t in tags if t] if tags else []
            if task_tags:
                if not all(t in task_tags for t in task.tags):
                    continue

            # Apply overdue filter
            if overdue:
                if today is not None:
                    # Task is overdue if due < today and not done
                    if task.due is not None and task.due < today and not task.done:
                        continue
                # If overdue is True but no today provided, skip overdue check for done tasks?
                # Spec says: "with overdue=True only open tasks whose due date is strictly before today are kept"
                # So if overdue=True and today is None, we should probably error or skip.
                # Re-reading: "Overdue=True without today raises ValueError"
                # So we raise ValueError if overdue=True and today is None.
                # My implementation above already raises ValueError. Good.

            # Apply status and date logic
            if overdue:
                # Open tasks only
                if not task.done:
                    if task.due is None or task.due < today:
                        continue
                # Done tasks are never overdue
                if task.due < today:
                    continue

            result.append(task)

        # Apply sorting
        if sort == "priority":
            result.sort(key=lambda t: (priority_key(t), t.id))
        elif sort == "due":
            result.sort(key=lambda t: (due_key(t), t.id))
        else:
            # sort == "id"
            result.sort(key=lambda t: (t.id, t.priority, t.title))

        return result

    def mark_done(self, task_id: int) -> Task:
        task = self.get(task_id)
        task.done = not task.done
        return task

    def remove(self, task_id: int) -> Task:
        for i, task in enumerate(self._tasks):
            if task.id == task_id:
                removed = task
                del self._tasks[i]
                return removed
        raise KeyError(f"Task with id {task_id} not found")

    def update_due_date(self, task_id: int, due: Optional[date]) -> None:
        task = self.get(task_id)
        task.due = due
