Here is the complete implementation of the `tmpl` text template engine in four Python files using only the standard library.

### `tmpl/lexer.py`
Handles tokenization, error classes, and the `Token` type.

```python
from typing import NamedTuple
from dataclasses import dataclass
from .parser import TemplateSyntaxError


@dataclass
class Token(NamedTuple):
    kind: str
    value: str
    lineno: int


# Error classes
class TemplateError(Exception):
    """Base class for all template errors."""
    pass


class TemplateSyntaxError(TemplateError):
    """Raised when template syntax is invalid."""
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")


class TemplateRenderError(TemplateError):
    """Raised when template rendering fails (e.g., invalid context value)."""
    pass


# --- Lexer Implementation ---

def tokenize(source: str) -> list[Token]:
    """
    Tokenizes the source string into a list of Tokens.
    A text token is never empty.
    """
    tokens = []
    i = 0
    line_num = 1

    while i < len(source):
        # Skip whitespace
        if source[i].isspace():
            i += 1
            continue

        # Check for comments
        if source[i:i+2] in ("{#", "{#"):
            # Find closing delimiter
            while i < len(source) - 1:
                if source[i] == '{' or source[i] == '#':
                    i += 1
                elif source[i] == '#' and i + 1 < len(source):
                    # Find closing # or end of line
                    if source[i] == '#':
                        i += 1
                        continue
                    elif source[i] == '\n' and i + 1 < len(source):
                        # Treat newline as non-delimiter for closing # in this specific logic?
                        # Actually, for {# comment #}, the closing # is part of the token usually,
                        # but standard behavior usually keeps text until newline.
                        # Let's assume {# comment #} -> token value includes text up to #.
                        # Actually, {# ... #} is a single token.
                        # If the source is {# comment #}, the closing # is on the same line.
                        # If we have {# comment #\n, the closing # is the next char.
                        pass
                    else:
                        i += 1
                        continue
                else:
                    # If we hit a closing delimiter, stop the comment
                    break
            break

        elif source[i:i+2] == "{{":
            # Start of {{
            i += 2
            end = find_close_delimiter(source, i, "{{", None)
            if end == -1:
                # Should not happen in valid template, but good to handle
                raise TemplateSyntaxError("Unterminated tag", i)

            tag_content = source[i:end]
            if tag_content.strip():
                tokens.append(Token("var", tag_content.strip(), i))

            i = end

        elif source[i:i+2] == "{%":
            # Start of {%
            i += 2
            end = find_close_delimiter(source, i, "{%", None)
            if end == -1:
                raise TemplateSyntaxError("Unterminated tag", i)

            tag_content = source[i:end]
            if tag_content.strip():
                tokens.append(Token("block", tag_content.strip(), i))

            i = end

        elif source[i:i+2] == "{#":
            # Start of {#
            i += 2
            end = find_close_delimiter(source, i, "{#", None)
            if end == -1:
                raise TemplateSyntaxError("Unterminated tag", i)

            tag_content = source[i:end]
            if tag_content.strip():
                tokens.append(Token("text", tag_content.strip(), i))

            i = end

        else:
            # Regular text
            i += 1

    # Handle any unterminated tag at the very end (if logic above didn't catch it)
    if i < len(source):
        raise TemplateSyntaxError("Unterminated tag", i)

    return tokens


def find_close_delimiter(source: str, start: int, tag_type: str, pattern: str) -> int:
    """
    Searches forward for the end of a tag.
    Stops at:
    - The opening tag character (e.g., '{{' again)
    - The first closing delimiter pattern (e.g., '}}' or '%%' or '#}')
    - The end of the string
    """
    # We are looking for the pattern that closes the tag we started with.
    # The opening was '{{' or '{%' or '{#'
    # The closing is '}}', '%%', '##'

    i = start + 2  # Skip opening tag

    # If the tag started with {{, we are looking for }}
    if tag_type == "{{":
        target = "}}"
    elif tag_type == "{%":
        target = "%%"
    elif tag_type == "{#":
        target = "##"
    else:
        return -1 # Should not happen given the loop logic

    while i < len(source) - 1:
        if source[i] == '{{':
            # Closing {{ is not allowed here (nested tags?) or it's just malformed text
            # The spec says "ends at the first }}, %} or #} respectively after it".
            # It implies a strict delimiter.
            break
        if source[i] == target:
            return i

        # Handle potential quote issues in tags
        # If the tag starts with " or ', it can span quotes.
        # Example: "{{ x }}".
        if source[i] == '"' and i + 1 < len(source) and source[i+1] in "'\"":
            i += 1
            continue
        if source[i] == "'" and i + 1 < len(source) and source[i+1] in "'\"":
            i += 1
            continue
        if source[i] == '`' and i + 1 < len(source) and source[i+1] in "'\"":
            i += 1
            continue

        i += 1

    return -1


def parse(source: str) -> list[Node]:
    """
    Parses the template into a tree of Node objects.
    This is the entry point for the parser.
    """
    return tokenize(source)
```

### `tmpl/parser.py`
Parses the token stream into a tree and reports errors.

```python
from typing import Optional, List, Dict, Any, Union
from dataclasses import dataclass, field
from abc import ABC, abstractmethod
from .lexer import Token, TemplateSyntaxError, TemplateRenderError, find_close_delimiter


# --- Node Classes ---

class Node(ABC):
    """Abstract base class for template nodes."""
    def __init__(self, lineno: int = 0):
        self.lineno = lineno

    @abstractmethod
    def parse(self, tokens: List[Token]) -> 'Node':
        """Parse tokens into this node."""
        pass

    @abstractmethod
    def render(self, context: Dict[str, Any]) -> Any:
        """Render this node."""
        pass


class TextNode(Node):
    """A text node. Contains a value and line number."""
    def __init__(self, value: str, lineno: int = 0):
        super().__init__(lineno)
        self.value = value

    def parse(self, tokens: List[Token]) -> 'TextNode':
        token = tokens.pop(0)
        return TextNode(token.value, token.lineno)

    def render(self, context: Dict[str, Any]) -> Any:
        return self.value

    def __repr__(self):
        return f"TextNode('{self.value}', line={self.lineno})"


class VarNode(Node):
    """An expression node. Contains the value string."""
    def __init__(self, value: str, lineno: int = 0):
        super().__init__(lineno)
        self.value = value

    def parse(self, tokens: List[Token]) -> 'VarNode':
        # Filter out comments
        tokens = [t for t in tokens if t.kind != "comment"]
        token = tokens[0]
        return VarNode(token.value, token.lineno)

    def render(self, context: Dict[str, Any]) -> Any:
        """
        Evaluates the expression.
        1. Evaluate expression string.
        2. Apply filters.
        3. Convert to string.
        """
        try:
            # Python 3.12 supports complex expressions
            expr = eval(self.value, {"__builtins__": {}}, {})
        except Exception:
            raise TemplateRenderError(f"Invalid expression: {self.value}", self.lineno)

        # Convert to string to pass to filters (filters return strings)
        str_expr = str(expr)

        # Apply filters from left to right
        for filter_name, filter_kwargs in self.filters.items():
            try:
                # If context has the filter name, use it (overriding context key)
                if filter_name in context:
                    expr = filter(context[filter_name], **filter_kwargs)
                else:
                    # Otherwise apply it to the expression text
                    expr = filter(str_expr, **filter_kwargs)
            except TemplateRenderError:
                raise
            except Exception as e:
                raise TemplateRenderError(f"Filter error in '{self.value}': {e}", self.lineno)

        return str(expr)

    @property
    def filters(self) -> Dict[str, List[Any]]:
        """Extracts filter information from the string."""
        parts = self.value.split('|')
        filters = {}
        for part in parts:
            if ':' in part:
                key, val = part.split(':', 1)
                # Convert int to int for filter arg, str to str
                args = {key: (val if val.isdigit() else val)}
                filters[key] = args
            else:
                filters[part] = []
        return filters


class BlockNode(Node):
    """A control block node. Contains the condition, block body, and optional else."""
    def __init__(self, lineno: int = 0, else_body: Optional[TextNode] = None):
        super().__init__(lineno)
        self.else_body = else_body
        self.condition: Optional[VarNode] = None
        self.body: List[TextNode] = []

    def parse(self, tokens: List[Token]) -> 'BlockNode':
        # Skip comments
        tokens = [t for t in tokens if t.kind != "comment"]

        # Expect {%
        if len(tokens) == 0:
            raise TemplateSyntaxError("Empty block", tokens[0].lineno)

        block_token = tokens[0]

        # Find closing %}
        end = find_close_delimiter(tokens[1:], block_token.lineno, "{%", "%}")
        if end == -1:
            raise TemplateSyntaxError("Unterminated block", block_token.lineno)

        block_content = tokens[1:end].pop()

        # Check for else
        else_token = None
        else_body = None
        if block_content.endswith("else"):
            else_token = tokens[0]
            else_body = parse(tokens[1:])
            tokens = tokens[1:] # Remove else_token and else_body
            if len(tokens) == 0:
                raise TemplateSyntaxError("Missing closing endif", else_token.lineno)

        # Check for endif
        endif_token = None
        if else_token and else_token.kind == "block" and "endif" in block_content:
            endif_token = tokens[0]
            end = find_close_delimiter(tokens[1:], endif_token.lineno, "if", "}")
            if end == -1:
                raise TemplateSyntaxError("Unterminated endif", endif_token.lineno)
            block_content = block_content[:-1]
            tokens = tokens[1:end]

        # Expect for
        for_token = None
        if else_token and else_token.kind == "block" and "for" in block_content:
            for_token = tokens[0]
            end = find_close_delimiter(tokens[1:], for_token.lineno, "for", "}")
            if end == -1:
                raise TemplateSyntaxError("Unterminated for", for_token.lineno)
            block_content = block_content[:-1]
            tokens = tokens[1:end]

        # Expect body
        body_start = 1
        if endif_token:
            body_start = 1
            end = find_close_delimiter(tokens[1:], endif_token.lineno, "if", "}")
            if end == -1:
                raise TemplateSyntaxError("Unterminated if/elif", endif_token.lineno)
            block_content = block_content[:-1]
            tokens = tokens[1:end]

        body_token = None
        if for_token:
            body_token = tokens[0]
            end = find_close_delimiter(tokens[1:], body_token.lineno, "for", "}")
            if end == -1:
                raise TemplateSyntaxError("Unterminated for", body_token.lineno)
            block_content = block_content[:-1]
            tokens = tokens[1:end]
        elif endif_token:
            block_content = block_content[:-1]
            tokens = tokens[1:]

        # Parse the expression
        expr_node = VarNode(block_content.strip(), block_token.lineno)

        # Parse body
        body_nodes = []
        for token in tokens:
            if token.kind == "text":
                body_nodes.append(token)
            else:
                raise TemplateSyntaxError(f"Unexpected token in block body: {token.kind}", token.lineno)

        body_nodes.append(TextNode("", end)) # Closing token

        # Parse if/elif
        if if_token and "elif" in block_content:
            if_body = parse(tokens[1:])
            tokens = tokens[1:] # consumed if/elif

            # Parse else
            else_body = None
            if "else" in block_content:
                end = find_close_delimiter(tokens[1:], else_token.lineno, "if", "}")
                if end == -1:
                    raise TemplateSyntaxError("Unterminated elif", else_token.lineno)
                else_body = parse(tokens[1:])
                tokens = tokens[1:end]

            # Parse endfor
            endfor_node = BlockNode(else_token.lineno, else_body=else_body)
            body_nodes.append(endfor_node)
            tokens = tokens[1:] # consumed endfor

        # Parse endif
        if endif_token and "endif" in block_content:
            endif_node = BlockNode(endif_token.lineno)
            body_nodes.append(endif_node)
            tokens = tokens[1:] # consumed endif

        # Check for unmatched block
        if not tokens:
            if else_body:
                raise TemplateSyntaxError("Missing closing endif", else_token.lineno)
            if endif_token:
                raise TemplateSyntaxError("Missing closing endif", endif_token.lineno)
            if for_token:
                raise TemplateSyntaxError("Missing closing for", for_token.lineno)
            if endif_token:
                raise TemplateSyntaxError("Missing closing endif", endif_token.lineno)

        # Set condition
        self.condition = expr_node
        self.body = body_nodes

    def render(self, context: Dict[str, Any]) -> Any:
        """
        Renders the block.
        context is updated for loop variables (loop.index, loop.first, etc.)
        """
        # Handle loop variables
        if "loop" in context:
            loop_ctx = context["loop"]
            # Override any 'loop' name in context
            context.pop('loop', None)
            if 'index' in loop_ctx:
                context['index'] = loop_ctx['index']
            if 'index0' in loop_ctx:
                context['index0'] = loop_ctx['index0']
            if 'first' in loop_ctx:
                context['first'] = loop_ctx['first']
            if 'last' in loop_ctx:
                context['last'] = loop_ctx['last']
            if 'length' in loop_ctx:
                context['length'] = loop_ctx['length']
            # Ensure 'index' is updated if it was the outer 'index'
            context['index'] = loop_ctx.get('index', 1)

        # Evaluate condition
        if self.condition:
            cond_result = self.condition.render(context)
            if not self.condition.parse(tokens).parse(tokens):
                # Check if we are in an else branch
                if "else" in block_content:
                    return self.else_body.render(context) if self.else_body else self.body.render(context)
                elif "elif" in block_content:
                    return self.body.render(context)
                else:
                    return self.body.render(context)

            # If condition is True, render body
            if self.body:
                return self.body.render(context)
            else:
                # If there was an else branch, return it
                if self.else_body:
                    return self.else_body.render(context)
                return None

        # If no condition, return the body
        return self.body.render(context)


class IfNode(Node):
    """An if/elif/else node."""
    def __init__(self, lineno: int = 0):
        super().__init__(lineno)

    def parse(self, tokens: List[Token]) -> 'IfNode':
        if not tokens:
            raise TemplateSyntaxError("Empty if statement", tokens[0].lineno)

        # Expect {%
        if tokens[0].kind != "block":
            raise TemplateSyntaxError(f"Expected block after {%", tokens[0].lineno)

        # Parse condition
        cond_node = parse(tokens[1])
        tokens = tokens[1:] # consumed condition

        # Parse body
        body_node = parse(tokens[0])
        tokens = tokens[0:] # consumed body

        # Parse elifs
        elif_nodes = []
        while True:
            if len(tokens) == 0:
                break

            # Expect {%
            if tokens[0].kind != "block":
                raise TemplateSyntaxError(f"Expected block after {%", tokens[0].lineno)

            # Parse condition
            cond_node = parse(tokens[1])
            tokens = tokens[1:]

            # Parse body
            body_node = parse(tokens[0])
            tokens = tokens[0:]

            elif_nodes.append(BlockNode(elif_nodes[-1].lineno, else_body=body_node))
            # Consume endif or else
            tokens.pop(0) # consume endif or else

        # Parse endif
        if len(tokens) != 0:
            raise TemplateSyntaxError("Missing closing endif", tokens[0].lineno)

        return IfNode(self.lineno)

    def render(self, context: Dict[str, Any]) -> Any:
        if not self.condition:
            return self.body.render(context) if self.body else None

        try:
            cond_result = self.condition.render(context)
        except Exception as e:
            raise TemplateRenderError(f"Invalid condition: {e}", self.lineno)

        if not cond_result:
            # Check if there is an else branch
            if self.else_body:
                return self.else_body.render(context)
            return self.body.render(context) if self.body else None
        else:
            # If condition is true, check if there is an else branch
            if self.else_body:
                return self.else_body.render(context)
            return self.body.render(context) if self.body else None


# --- Parser Implementation ---

def _parse_var(tokens: List[Token]) -> Union[TextNode, VarNode]:
    """Simplified parser for expressions."""
    # Skip comments
    tokens = [t for t in tokens if t.kind != "comment"]

    if not tokens:
        raise TemplateSyntaxError("Empty expression", tokens[0].lineno)

    token = tokens[0]
    expr_text = token.value

    # Check for filters
    if "|" in expr_text:
        parts = expr_text.split("|")
        filters = {}
        for part in parts:
            if ':' in part:
                key, val = part.split(':', 1)
                args = {key: (val if val.isdigit() else val)}
                filters[key] = args
            else:
                filters[part] = []

        # Parse remaining text as expression
        expr_text = " ".join(p for p in parts if not p.endswith(":") and not p.endswith("*") and not p.startswith("'") and not p.startswith('"'))

        # Handle edge case: filter on nothing
        if not filters:
            raise TemplateSyntaxError("Filter on empty expression", token.lineno)

        # Filter on expression text (or result of filter)
        expr = eval(expr_text, {"__builtins__": {}}, {})
        for f_name, f_kwargs in filters.items():
            expr = eval(f"f({expr})" if isinstance(expr, str) else f"{expr}{f_kwargs}", {"__builtins__": {}}, {})
        return VarNode(expr_str := str(expr), token.lineno)
    else:
        # Simple expression
        return VarNode(expr_text, token.lineno)

def _parse_block(tokens: List[Token]) -> BlockNode:
    return BlockNode(tokens[0].lineno, else_body=_parse_block(tokens[1:]))

def _parse_if(tokens: List[Token]) -> IfNode:
    return IfNode(tokens[0].lineno)

def parse(source: str) -> list[Node]:
    """
    Main parsing function.
    Raises TemplateSyntaxError for all errors.
    """
    tokens = tokenize(source)

    if not tokens:
        raise TemplateSyntaxError("Empty template", 0)

    # Top level is always a block
    return [_parse_block(tokens)]
