### `tmpl/render.py`
Handles rendering logic, including the context merging logic.

```python
from typing import Union, Dict, Any, Optional
from .parser import parse, render as _render
from .lexer import Token, TemplateSyntaxError, TemplateRenderError, find_close_delimiter


class Template:
    def __init__(self, source: str):
        self.source = source
        # Parse immediately to catch errors
        _parse(self.source)

    def render(self, context: Union[Dict[str, Any], None] = None, **kwargs) -> str:
        # Merge context and kwargs (kwargs win)
        merged = context.copy() if context else {}
        for key, value in kwargs.items():
            merged[key] = value

        return _render(self.source, merged)

    def _render(self, source: str, context: Dict[str, Any]) -> str:
        """Internal render logic."""
        if not source:
            return ""

        # Handle comments first (text)
        comment_tokens = []
        for t in tokenize(source):
            if t.kind == "comment":
                comment_tokens.append(t)
            else:
                break

        text_tokens = comment_tokens
        tokens = [t for t in source if t.kind != "comment"]

        # Parse top-level block
        nodes = parse(source)

        # Render blocks
        current_idx = 0
        while current_idx < len(nodes):
            node = nodes[current_idx]

            if isinstance(node, BlockNode):
                # Check for endif
                if not node.else_body:
                    while current_idx < len(nodes) and not isinstance(nodes[current_idx], BlockNode):
                        current_idx += 1

                if current_idx < len(nodes) and isinstance(nodes[current_idx], BlockNode):
                    next_node = nodes[current_idx]

                    if next_node.else_body:
                        # Found else branch
                        if current_idx + 1 < len(nodes):
                            current_idx += 1
                        return self._render(source, merged)

                    # Render condition
                    try:
                        cond_result = node.condition.render(merged)
                    except TemplateRenderError:
                        raise

                    if not cond_result:
                        # Render else if exists
                        if next_node.else_body:
                            return self._render(source, merged)
                        return self._render(source, merged)
                    else:
                        # Render body
                        return self._render(source, merged)

            elif isinstance(node, IfNode):
                # Render if/elif/else
                if not node.condition:
                    return self._render(source, merged)

                try:
                    cond_result = node.condition.render(merged)
                except TemplateRenderError:
                    raise

                if not cond_result:
                    # Render else if exists
                    if next_node.else_body:
                        return self._render(source, merged)
                    return self._render(source, merged)
                else:
                    # Render body
                    return self._render(source, merged)

            elif isinstance(node, VarNode):
                # Render expression
                return _render(source, merged)

            elif isinstance(node, TextNode):
                return node.value

        # If no blocks found, return source text
        return source
