from typing import Optional, List, Dict, Any, Union
from dataclasses import dataclass, field
from abc import ABC, abstractmethod
from .lexer import Token, TemplateNotFound, TemplateSyntaxError, find_close_delimiter


# --- Node Classes ---

class Node(ABC):
    def __init__(self, lineno: int = 0):
        self.lineno = lineno

    @abstractmethod
    def parse(self, tokens: List[Token]) -> 'Node':
        pass

    @abstractmethod
    def render(self, context: Dict[str, Any]) -> Any:
        pass


class TextNode(Node):
    def __init__(self, value: str, lineno: int = 0):
        super().__init__(lineno)
        self.value = value

    def parse(self, tokens: List[Token]) -> 'TextNode':
        token = tokens.pop(0)
        return TextNode(token.value, token.lineno)

    def render(self, context: Dict[str, Any]) -> Any:
        return self.value

    def __repr__(self):
        return f"TextNode('{self.value}', line={self.lineno})"


class VarNode(Node):
    def __init__(self, value: str, lineno: int = 0):
        super().__init__(lineno)
        self.value = value

    def parse(self, tokens: List[Token]) -> 'VarNode':
        token = tokens.pop(0)
        return VarNode(token.value, token.lineno)

    def render(self, context: Dict[str, Any]) -> Any:
        try:
            expr = eval(self.value, {"__builtins__": {}}, {})
        except Exception:
            raise TemplateRenderError(f"Invalid expression: {self.value}", self.lineno)

        str_expr = str(expr)

        for filter_name, filter_kwargs in self.filters.items():
            try:
                if filter_name in context:
                    expr = filter(context[filter_name], **filter_kwargs)
                else:
                    expr = filter(str_expr, **filter_kwargs)
            except TemplateRenderError:
                raise
            except Exception as e:
                raise TemplateRenderError(f"Filter error: {e}", self.lineno)

        return str(expr)

    @property
    def filters(self) -> Dict[str, List[Any]]:
        parts = self.value.split('|')
        filters = {}
        for part in parts:
            if ':' in part:
                key, val = part.split(':', 1)
                args = {key: (val if val.isdigit() else val)}
                filters[key] = args
            else:
                filters[part] = []
        return filters


class BlockNode(Node):
    def __init__(self, lineno: int = 0, else_body: Optional[TextNode] = None):
