        while True:
            if len(tokens) == 0:
                break

            if tokens[0].kind != "block":
                raise TemplateSyntaxError(f"Expected block after {%", tokens[0].lineno)

            cond_node = parse(tokens[1])
            tokens = tokens[1:]

            body_node = parse(tokens[0])
            tokens = tokens[0:]

            elif_nodes.append(BlockNode(elif_nodes[-1].lineno, else_body=body_node))
            tokens.pop(0) 

        if len(tokens) != 0:
            raise TemplateSyntaxError("Missing closing endif", tokens[0].lineno)

        return IfNode(self.lineno)

    def render(self, context: Dict[str, Any]) -> Any:
        if not self.condition:
            return self.body.render(context) if self.body else None

        try:
            cond_result = self.condition.render(context)
        except Exception as e:
            raise TemplateRenderError(f"Invalid condition: {e}", self.lineno)

        if not cond_result:
            if self.else_body:
                return self.else_body.render(context)
            return self.body.render(context) if self.body else None
        else:
            if self.else_body:
                return self.else_body.render(context)
            return self.body.render(context) if self.body else None


# --- Parser Implementation ---

def _parse_var(tokens: List[Token]) -> Union[TextNode, VarNode]:
    tokens = [t for t in tokens if t.kind != "comment"]

    if not tokens:
        raise TemplateSyntaxError("Empty expression", tokens[0].lineno)

    token = tokens[0]
    expr_text = token.value

    if "|" in expr_text:
        parts = expr_text.split("|")
        filters = {}
        for part in parts:
            if ':' in part:
                key, val = part.split(':', 1)
                args = {key: (val if val.isdigit() else val)}
                filters[key] = args
            else:
                filters[part] = []

        expr_text = " ".join(p for p in parts if not p.endswith(":") and not p.endswith("*") and not p.startswith("'") and not p.startswith('"'))

        if not filters:
            raise TemplateSyntaxError("Filter on empty expression", token.lineno)

        expr = eval(expr_text, {"__builtins__": {}}, {})
        for f_name, f_kwargs in filters.items():
            expr = eval(f"f({expr})" if isinstance(expr, str) else f"{expr}{f_kwargs}", {"__builtins__": {}}, {})
        return VarNode(str(expr), token.lineno)
    else:
        return VarNode(expr_text, token.lineno)

def _parse_block(tokens: List[Token]) -> BlockNode:
    return BlockNode(tokens[0].lineno, else_body=_parse_block(tokens[1:]))

def _parse_if(tokens: List[Token]) -> IfNode:
    return IfNode(tokens[0].lineno)

def _parse_extends(tokens: List[Token]) -> BlockNode:
    if not tokens:
        raise TemplateSyntaxError("Empty extends", tokens[0].lineno)

    if tokens[0].kind != "block":
        raise TemplateSyntaxError(f"Expected block after {% extends", tokens[0].lineno)

    block_token = tokens[0]

    end = find_close_delimiter(tokens[1:], block_token.lineno, "{%", "%}")
    if end == -1:
        raise TemplateSyntaxError("Unterminated extends", block_token.lineno)

    block_content = tokens[1:end].pop()

    if block_content.startswith("extends"):
        # Parse name
        if block_content.startswith("extends '"):
            name = block_content[9:-1]
        elif block_content.startswith("extends \""):
            name = block_content[9:-1]
        else:
            raise TemplateSyntaxError(f"Invalid extends name: {block_content}", block_token.lineno)

        tokens = tokens[1:]

        # Find closing %}
        end = find_close_delimiter(tokens, 0, "{%", "%}")
        if end == -1:
            raise TemplateSyntaxError("Unterminated extends", tokens[0].lineno)

        block_content = tokens[1:end].pop()

        if "else" in block_content:
            else_body = parse(tokens[1:])
            tokens = tokens[1:]
        else:
            else_body = None

        return BlockNode(end, else_body=else_body)

def _parse_for(tokens: List[Token]) -> BlockNode:
    if not tokens:
        raise TemplateSyntaxError("Empty for", tokens[0].lineno)

    if tokens[0].kind != "block":
        raise TemplateSyntaxError(f"Expected block after {% for", tokens[0].lineno)

    block_token = tokens[0]

    end = find_close_delimiter(tokens[1:], block_token.lineno, "{%", "%}")
    if end == -1:
        raise TemplateSyntaxError("Unterminated for", block_token.lineno)

    block_content = tokens[1:end].pop()

    if "else" in block_content:
        else_body = parse(tokens[1:])
        tokens = tokens[1:]
    else:
        else_body = None

    return BlockNode(end, else_body=else_body)

def parse(source: str) -> list[Node]:
    """
    Main parsing function.
    """
    return tokenize(source)
