```python
from typing import Union, Dict, Any, Optional, List
from dataclasses import dataclass
from html import escape as _escape
from .lexer import Token, TemplateNotFound, TemplateSyntaxError, TemplateRenderError, find_close_delimiter


class DictLoader:
    """Loads template sources from a dictionary of names."""
    def __init__(self, templates: dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        try:
            return self.templates[name]
        except KeyError:
            raise TemplateNotFound(name)

    def __repr__(self):
        return f"DictLoader({list(self.templates.keys())})"


class Environment:
    def __init__(self, loader=None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape

    def get_template(self, name: str) -> 'Template':
        if not self.loader:
            raise TemplateNotFound(name)

        try:
            source = self.loader.get_source(name)
        except TemplateNotFound:
            raise TemplateNotFound(name)
        except Exception as e:
            raise TemplateSyntaxError(f"Error loading template: {e}", name)

        return Template(source, loader=self.loader, autoescape=self.autoescape, name=name)

    def from_string(self, source: str) -> 'Template':
        if not source:
            raise TemplateSyntaxError("Empty template", 0)
        return Template(source, autoescape=self.autoescape, name=None)


class Template:
    def __init__(self, source: str, *, loader=None, autoescape: bool = False, name: str | None = None):
        self.source = source
        self.loader = loader
        self.autoescape = autoescape
        self.name = name

    def render(self, context: Union[Dict[str, Any], None] = None, **kwargs) -> str:
        if self.name is None:
            raise TemplateSyntaxError("Template has no name", 0)

        # Merge context and kwargs (kwargs win)
        merged = context.copy() if context else {}
        for key, value in kwargs.items():
            merged[key] = value

        return self._render(source, merged)

    def _render(self, source: str, context: Dict[str, Any]) -> str:
        if not source:
            return ""

        # Handle comments first (text)
        comment_tokens = []
        for t in tokenize(source):
            if t.kind == "comment":
                comment_tokens.append(t)
            else:
                break

        text_tokens = comment_tokens
        tokens = [t for t in source if t.kind != "comment"]

        # Parse top-level block
        nodes = parse(source)

        # Render blocks
        current_idx = 0
        while current_idx < len(nodes):
            node = nodes[current_idx]

            if isinstance(node, BlockNode):
                if not node.else_body:
                    while current_idx < len(nodes) and not isinstance(nodes[current_idx], BlockNode):
                        current_idx += 1

                if current_idx < len(nodes) and isinstance(nodes[current_idx], BlockNode):
                    next_node = nodes[current_idx]

                    if next_node.else_body:
                        if current_idx + 1 < len(nodes):
                            current_idx += 1
                        return self._render(source, merged)

                    if not self.autoescape:
                        return self._render(source, merged)
                    else:
                        # Autoescape: escape the result before returning it
                        # But wait, autoescaping applies to {{ }} tags. 
                        # The return statement here is after all blocks.
                        # The spec says: "The output of {{ super() }} and of blocks is already rendered template output and is never escaped again"
                        # So we only escape the *tags inside* the blocks.
                        pass

                    # Render condition
                    try:
                        cond_result = node.condition.render(merged)
                    except TemplateRenderError:
                        raise

                    if not cond_result:
                        if next_node.else_body:
                            return self._render(source, merged)
                        return self._render(source, merged)
                    else:
                        if self.autoescape:
                            result = self._render(source, merged)
                        else:
                            result = self._render(source, merged)

                        if result is None:
                            return None
                        return result

            elif isinstance(node, IfNode):
                if not node.condition:
                    return self._render(source, merged)

                try:
                    cond_result = node.condition.render(merged)
                except Exception as e:
                    raise TemplateRenderError(f"Invalid condition: {e}", node.lineno)

                if not cond_result:
                    if next_node.else_body:
                        return self._render(source, merged)
                    return self._render(source, merged)
                else:
                    if self.autoescape:
                        result = self._render(source, merged)
                    else:
                        result = self._render(source, merged)

                    if result is None:
                        return None
                    return result

            elif isinstance(node, VarNode):
                return _render(source, merged)

            elif isinstance(node, TextNode):
                return node.value

        return source
