def render_blocks(blocks: list[tuple]) -> str:
    """
    Renders blocks joined by "\n".
    """
    if not blocks:
        return ""
    result = []
    for block in blocks:
        if block[0] == 'code':
            lang = block[1]
            code = block[2]
            result.append('<pre><code class="language-' + lang + '"><pre>' + code + '</pre></code></pre>')
        elif block[0] == 'heading':
            result.append('<h' + str(block[1]) + '>inline</h' + str(block[1]) + '>')
        elif block[0] == 'hr':
            result.append('<hr />')
        elif block[0] == 'blockquote':
            result.append('<blockquote>')
            result.append('\n')
            for child in block[1]:
                result.append(render_blocks(child))
            result.append('\n</blockquote>')
        elif block[0] == 'list':
            ordered = block[1]
            start = block[2]
            items = block[3]
            if ordered:
                result.append('<ol start="' + str(start) + '">' + '\n'.join('<li>' + item + '</li>' for item in items) + '\n</ol>')
            else:
                result.append('<ul>')
                for item in items:
                    result.append('\n<li>' + item + '</li>')
                result.append('\n</ul>')
        elif block[0] == 'paragraph':
            result.append('<p>' + block[1] + '</p>')
    return '\n'.join(result)


def to_html(text: str) -> str:
    """
    Convenience function: parse_blocks -> render_blocks -> render_inline -> escape_html
    """
    blocks = parse_blocks(text)
    rendered = render_blocks(blocks)
    return render_inline(rendered)


