def parse_blocks(text: str) -> list[tuple]:
    """
    Splits a document into blocks.
    Returns a list of tuples: (type, content, ...).
    """
    lines = text.split('\n')
    blocks = []

    i = 0
    while i < len(lines):
        line = lines[i]

        # Skip empty lines (blank lines)
        if not line.strip():
            i += 1
            continue

        # Check for fenced code
        if line.strip().startswith('`'):
            lang = None
            code_lines = []
            i += 1
            # Skip leading spaces of fence line
            while i < len(lines) and lines[i].strip() == '':
                i += 1

            # Parse language
            parts = line.strip().split(None, 1)
            if len(parts) == 2:
                lang = parts[0]
                i += 1
            elif parts[0] == '':
                lang = ""

            # Add empty line to content if present in original text
            if i < len(lines):
                code_lines.append('')

            i += 1
            while i < len(lines):
                if lines[i].strip() == '```':
                    # Closing fence
                    code_lines.append('')
                    break
                if i < len(lines):
                    code_lines.append(lines[i])
                i += 1

            # If no closing fence, add empty line to content
            if i < len(lines):
                code_lines.append('')

            if lang is not None:
                lang = escape_html(lang)
            else:
                lang = ""

            blocks.append(('code', lang, ''.join(code_lines)))
            continue

        # Check for heading
        if line.strip().startswith('#'):
            text = line[len('#'):].strip()
            # Strip trailing #
            while text.startswith('#'):
                text = text[1:]

            blocks.append(('heading', 1, text))
            continue

        # Check for horizontal rule
        if re.match(r'^[{*_]{3,}}.*$', line):
            blocks.append(('hr',))
            i += 1
            continue

        # Check for blockquote
        if line.strip().startswith('>'):
            blockquote_lines = [line]
            i += 1
            while i < len(lines):
                next_line = lines[i]
                # End of blockquote at first non-quote line
                if not next_line.startswith('>'):
                    break
                blockquote_lines.append(next_line)
                i += 1
            blockquote_text = '\n'.join(''.join(b[2:]) for b in blockquote_lines)
            blocks.append(('blockquote', blockquote_text))
            continue

        # Check for list
        if re.match(r'^[-*+]\s+|^\d+\.\s+', line):
            ordered = bool(re.match(r'^\d+\.', line))
            start = None
            items = []

            # Parse first item
            parts = line.strip().split(None, 1)
            if len(parts) == 1:
                # Bullet list
                start = None
                text = parts[0]
                i += 1
                while i < len(lines):
                    next_line = lines[i]
                    if next_line.strip() == '':
                        # Blank line ends list
                        break
                    if next_line.strip().startswith('-') or next_line.strip().startswith('*') or next_line.strip().startswith('+'):
                        # Check if item of same kind
                        next_parts = next_line.strip().split(None, 1)
                        if len(next_parts) == 1:
                            # Same bullet
                            text += '\n' + next_line
                        elif len(next_parts) > 1 and next_parts[0] != '':
                            # Different bullet or start of list
                            if start is not None:
                                blocks.append(('list', ordered, start, items))
                                items.append(text)
                                start = None
                            text = next_line
                        else:
                            # Start of new ordered list
                            if ordered:
                                blocks.append(('list', ordered, None, items))
                                start = None
                            else:
                                # Blank line or different marker ends list
                                blocks.append(('list', ordered, start, items))
                                items.append(text)
                            start = None
                            text = next_line
                    else:
                        # Continuation
                        text += '\n' + next_line
                    i += 1

            else:
                # Ordered list
                if parts[1] == '':
                    # Start of new ordered list
                    start = int(parts[0])
                    items = []
                    i += 1
                    while i < len(lines):
                        next_line = lines[i]
                        if next_line.strip() == '':
                            # Blank line ends list
                            break
                        if next_line.strip().startswith('-') or next_line.strip().startswith('*') or next_line.strip().startswith('+'):
                            # Check if item of same kind
                            next_parts = next_line.strip().split(None, 1)
                            if len(next_parts) == 1:
                                text = next_line
                            elif len(next_parts) > 1 and next_parts[0] != '':
                                if start is not None:
                                    blocks.append(('list', ordered, start, items))
                                    items.append(text)
                                    start = None
                                text = next_line
                            else:
                                if ordered:
                                    blocks.append(('list', ordered, start, items))
                                    start = None
                                    text = next_line
                                else:
                                    blocks.append(('list', ordered, start, items))
                                    start = None
                                    text = next_line
                        else:
                            text += '\n' + next_line
                        i += 1

                # Check for list continuation
                if i < len(lines):
                    next_line = lines[i]
                    if not next_line.strip() and not next_line.strip().startswith('-') and not next_line.strip().startswith('*') and not next_line.strip().startswith('+'):
                        # Blank line ends list
                        pass
                    elif next_line.strip().startswith('-') or next_line.strip().startswith('*') or next_line.strip().startswith('+'):
                        # Check if item of same kind
                        next_parts = next_line.strip().split(None, 1)
                        if len(next_parts) == 1:
                            # Same bullet
                            text += '\n' + next_line
                        elif len(next_parts) > 1 and next_parts[0] != '':
                            # Different bullet or start of list
                            if ordered:
                                blocks.append(('list', ordered, start, items))
                                items.append(text)
                                start = None
                            text = next_line
                        else:
                            # Start of new ordered list
                            if ordered:
                                blocks.append(('list', ordered, start, items))
                                start = None
                            else:
                                # Blank line or different marker ends list
                                blocks.append(('list', ordered, start, items))
                                items.append(text)
                            start = None
                            text = next_line
                    else:
                        # Continuation
                        text += '\n' + next_line
                else:
                    text += '\n'

                items = [escape_html(item) for item in items]
                blocks.append(('list', ordered, start, items))
            continue

        # Check for table
        # A table starts at a line that does not begin with a space, contains a |,
        # and is directly followed by a delimiter row with the same number of cells.

        # Find table start index
        table_start_idx = None
        header_rows = []
        body_rows = []

        j = i + 1
        while j < len(lines):
            next_line = lines[j]
            if not next_line.strip():
                j += 1
                continue

            # Check if next line is a header row (starts with | and has valid delimiter cells)
            # We need to verify it matches the structure of the header
            # First, let's determine if the current line (or the one we just read) is a header.
            # We'll check if the next non-empty line is a delimiter row.

            # Parse potential header row
            if not next_line.strip().startswith('|'):
                j += 1
                continue

            # This is the header row candidate
            # Extract header cells
            header_cells = []
            temp_line = next_line.strip()
            # Remove escaped |
            while temp_line.startswith('\\|'):
                temp_line = temp_line[2:]
                header_cells.append('')
                temp_line = temp_line.strip()
                # Split by |
                parts = temp_line.split('|')
                clean_parts = []
                for p in parts:
                    c = p.strip()
                    if len(c) > 1 and (c[0] == '|' or c[-1] == '|'):
                        c = c[1:-1]
                    clean_parts.append(c)
                header_cells.append(' '.join(clean_parts))

            # Check if all cells match delimiter format (one or more -, optional :, optional :)
            # Actually, spec: "one or more -", optional : at either end.
            # So pattern is ^-+:?$ or :^-+:?$ or :^-+:?$?
            # Let's be strict: all cells must be present and match
            delimiter_pattern = re.compile(r'^[?]*:[?]*$')
            is_delimiter = True
            for cell in header_cells:
                if not cell:
                    is_delimiter = False
                    break
                if not cell.startswith('\\|') and cell != '-':
                    is_delimiter = False
                    break

            if is_delimiter:
                # Verify alignment for header row
                row_aligns = []
                for cell in header_cells:
                    if cell.startswith('\\|'):
                        row_aligns.append(None)
                        cell = cell[2:].strip()
                        if len(cell) > 1 and (cell[0] == ':' or cell[-1] == ':'):
                            row_aligns.append('')
                        else:
                            row_aligns.append('left')
                        cell = cell.strip()
                    elif cell == ':':
                        row_aligns.append(None)
                        cell = ''
                    elif cell == '':
                        row_aligns.append('')
                        cell = ''
                    else:
                        row_aligns.append('left')
                        cell = cell
                    row_aligns.append('left')

                # If header row has valid alignment, it is a header
                # We also need to check if the next line is also a header (delimiter row)
                # According to spec: "is directly followed by a delimiter row"
                # This implies the line itself is the header row and the next line is the delimiter.
                # However, often headers are followed by body rows.
                # Re-reading spec: "A table starts at a line ... directly followed by a delimiter row".
                # This means the line starting the table is the header row, and the NEXT line is the delimiter row.
                # So we need to check if the next line is a valid header row.

                # Let's check the next line
                if j + 1 < len(lines):
                    next_line2 = lines[j + 1]
                    if not next_line2.strip():
                        j += 1
                        continue

                    next_cells = []
                    temp_next = next_line2.strip()
                    while temp_next.startswith('\\|'):
                        temp_next = temp_next[2:]
                        next_cells.append('')
                        temp_next = temp_next.strip()
                    parts = temp_next.split('|')
                    clean_parts = []
                    for p in parts:
                        c = p.strip()
                        if len(c) > 1 and (c[0] == '|' or c[-1] == '|'):
                            c = c[1:-1]
                        clean_parts.append(c)
                    next_cells.append(' '.join(clean_parts))

                    # Check if next row is a valid delimiter row (all cells valid)
                    all_valid = True
                    for cell in next_cells:
                        if not cell.startswith('\\|') and cell != '-':
                            all_valid = False
                            break
                    if all_valid:
                        # This is a valid table start
                        # Check if the current line (header) has valid alignment
                        header_has_valid_align = all(a not in ('', None) for a in row_aligns)
                        if header_has_valid_align:
                            table_start_idx = j
                            header_rows.append(header_cells)
                            is_table = True
                            table_aligns = row_aligns
                            table_header_aligns = row_aligns
                            break
                    else:
                        # Not a header row, treat as body
                        body_rows.append(header_cells)
                        is_table = False
                        table_start_idx = None
                        header_rows = []
                        is_delimiter = False
                    break
            else:
                # Not a header row, treat as body
                body_rows.append(header_cells)
                is_table = False
                table_start_idx = None
                header_rows = []
                is_delimiter = False
            j += 1

        if table_start_idx is not None:
            # Process the table
            if table_aligns is None:
                # Fallback alignment (all left)
