def escape_html(text: str) -> str:
    """
    Replaces &, <, >, and " with &amp;, &lt;, &gt;, and &quot; respectively.
    Priority ensures & is never escaped twice. ' is left alone.
    """
    return (text
            .replace('&', '&amp;')
            .replace('<', '&lt;')
            .replace('>', '&gt;')
            .replace('"', '&quot;'))


