"""
fsm/ - A minimal finite-state machine library.

Provides a generic FSM for state machines with:
- State management (enter/exit hooks)
- Event handling with guards and actions
- Internal transitions
- Listener callbacks
"""
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

from .machine import (
    Event,
    GuardRejected,
    InvalidTransition,
    Machine,
    MachineError,
    State,
    Transition,
)


__all__ = [
    # Exceptions
    "MachineError",
    "InvalidTransition",
    "GuardRejected",
    # Data Classes
    "State",
    "Transition",
    "Event",
    # Factory
    "Machine",
]


@dataclass
class State:
    """A state in a finite state machine."""
    name: str
    on_enter: Optional[Callable[[Machine, Event], None]] = field(default=None, repr=False)
    on_exit: Optional[Callable[[Machine, Event], None]] = field(default=None, repr=False)
    on_transition: List[Callable[[Machine, Event, str], None]] = field(default_factory=list, repr=False)

    def __post_init__(self):
        if not isinstance(self.on_enter, list):
            self.on_enter = [self.on_enter]
        if not isinstance(self.on_exit, list):
            self.on_exit = [self.on_exit]
        if not isinstance(self.on_transition, list):
            self.on_transition = [self.on_transition]


@dataclass
class Transition:
    """A transition in a finite state machine."""
    event: str
    source: Union[State, str, List[str], Tuple[str, ...], "*"]
    target: Union[State, str, List[str], Tuple[str, ...], None]
    guard: Optional[Callable[[Machine, Event], bool]] = None
    action: Optional[Callable[[Machine, Event], None]] = None

    def __post_init__(self):
        if not isinstance(self.source, list):
            self.source = [self.source]
        if not isinstance(self.target, list):
            self.target = [self.target]
        if not isinstance(self.guard, list):
            self.guard = [self.guard]
        if not isinstance(self.action, list):
            self.action = [self.action]

    def __repr__(self) -> str:
        return f"Transition(event={self.event!r}, source={self.source!r}, target={self.target!r}, guard={self.guard!r})"


@dataclass
class Event:
    """An event that can trigger a transition."""
    name: str
    source: Union[State, str, List[str], Tuple[str, ...], "*"]
    target: Union[State, str, List[str], Tuple[str, ...], None]
    data: Dict[str, Any]

    def __post_init__(self):
        if not isinstance(self.source, list):
            self.source = [self.source]
        if not isinstance(self.target, list):
            self.target = [self.target]
        if not isinstance(self.data, list):
            self.data = [self.data]


class MachineError(Exception):
    """Base class for machine errors."""
    pass


class InvalidTransition(MachineError):
    """Raised by fire() when no transition is available for the current event."""
    def __init__(self, state: str, event: str):
        super().__init__(f"No transition for {event!r} in state {state!r}")
        self.state = state
        self.event = event


class GuardRejected(MachineError):
    """Raised by fire() when all transitions for the event are rejected by their guards."""
    def __init__(self, state: str, event: str):
        super().__init__(f"All transitions for {event!r} rejected in state {state!r}")
        self.state = state
        self.event = event
