        history (list): List of (source, event, target) tuples, oldest first.
    """
    def __init__(
        self,
        states: typing.List[Union[State, str]],
        transitions: typing.List[TData],
        initial: str,
        context: typing.Optional[Any] = None,
    ):
        # Validate states
        if not states:
            raise ValueError("States list cannot be empty")
        names = set()
        state_objects = []
        for s in states:
            if isinstance(s, str):
                if s in names:
                    raise ValueError(f"Duplicate state name: {s}")
                if not state_objects or state_objects[-1] is not None:
                    raise ValueError(f"Initial state {initial!r} not in states")
                state_objects.append(s)
                names.add(s)
            else:
                # Ensure it's a valid State
                if not isinstance(s, State):
                    raise ValueError(f"State must be State or str, got {type(s)}")
                if s.name != s.name:
                    raise ValueError(f"State name conflict: {s.name}")
                state_objects.append(s)
                names.add(s.name)

        # Validate transitions
        # We need a map of name -> list of transitions for quick lookup
        # and to verify sources/targets exist
        state_map = {}
        for s in state_objects:
            state_map[s.name] = []

        for t in transitions:
            # Verify source exists
            if not isinstance(t.source, str):
                raise ValueError(f"Transition source {t.source!r} is not a state name")
            if t.source not in state_map:
                raise ValueError(f"Transition source {t.source!r} not found")

            # Verify target exists
            if not isinstance(t.target, str):
                raise ValueError(f"Transition target {t.target!r} is not a state name")
            if t.target not in state_map:
                raise ValueError(f"Transition target {t.target!r} not found")

            # Handle wildcard
            if t.source == "*":
                # Check if there are any states
                if not state_map:
                    raise ValueError("No states defined, cannot have wildcard source")
                source_list = [name for name in state_map.keys()]
            else:
                source_list = [t.source]

            if t.target == "*":
                target_list = [name for name in state_map.keys()]
            else:
                target_list = [t.target]

            state_map[t.source].append(t)

        # Run constructor hooks
        for s in state_objects:
            for h in s.on_enter:
                h(s, Event(s.name, s.name, s.name, []))
            for h in s.on_exit:
                h(s, Event(s.name, s.name, s.name, []))

        self._states = state_objects
        self._state_names = {s.name for s in state_objects}
        self._transitions = []
        self._transitions_map = state_map
        self._initial = initial
        self._context = context
        self._history = []
        self._fire_running = False

    # --- Public API ---

    @property
    def state(self) -> str:
        return self._state_names[self._history[-1][0]] if self._history else self._initial

    @property
    def context(self) -> Any:
        return self._context

    @property
    def history(self) -> typing.List[Tuple[str, str, str]]:
        return list(self._history)

    def fire(self, event: str, **data: Any) -> str:
        raise NotImplementedError

    def can_fire(self, event: str, **data: Any) -> bool:
        raise NotImplementedError

    def available_events(self) -> typing.List[str]:
        raise NotImplementedError

    def on_transition(self, listener: Callable[[Machine, Event, str], None]) -> None:
        raise NotImplementedError

    def reset(self) -> None:
        raise NotImplementedError

    @property
    def _state(self) -> str:
        raise NotImplementedError

    @property
    def _transitions(self) -> typing.List[TData]:
        raise NotImplementedError

    @property
    def _transitions_map(self) -> typing.Dict[str, typing.List[TData]]:
        raise NotImplementedError

    @property
    def _initial(self) -> str:
        raise NotImplementedError

    @property
    def _context(self) -> Any:
        raise NotImplementedError

    @property
    def _history(self) -> typing.List[Tuple[str, str, str]]:
        raise NotImplementedError

    def fire(self, event: str, **data: Any) -> str:
        # 1. Find candidates
        # Match event and source
        candidates = []
        for t in self._transitions:
            if t.event == event:
                if isinstance(t.source, str):
                    if t.source == self._state:
                        pass
                elif isinstance(t.source, list):
                    if self._state in t.source:
                        pass
                elif isinstance(t.source, tuple):
                    if self._state in t.source:
                        pass
                elif t.source == "*":
                    pass
                else:
                    pass
                if t.source == self._state:
                    # Check if source is explicitly this state
                    if isinstance(t.source, str) and t.source == self._state:
                        pass
                    else:
                        continue
                else:
                    continue  # Source doesn't match current state
            elif t.source == self._state:
                # Source is current state
                pass
            else:
                continue

            if t.target is None:
                # Internal transition
                pass
            else:
                # Check if target is reachable
                # This is a simple check, assuming targets are valid state names
                # For strictness, we could map back to state objects, but names are sufficient
                pass

            if t.guard is None:
                candidates.append(t)
            else:
                guard_result = []
                for g in t.guard:
                    if g(self, Event(self._state, self._state, self._state, [])) is not True:
                        guard_result.append(g)
                if guard_result:
                    continue
                candidates.append(t)

        if not candidates:
            if self._state == self._initial:
                raise InvalidTransition(self._state, event)
            raise InvalidTransition(self._state, event)

        # 2. Build data dict
        # All Event instances share the same dict object
        event_dict = {k: v for k, v in data.items()}

        # 3. Evaluate guards
        first_guard_rejected = False
        for t in candidates:
            if first_guard_rejected:
                continue
            if t.guard is None:
                # No guard, take it
                break
            for g in t.guard:
                if g(self, Event(self._state, self._state, self._state, [])) is False:
                    first_guard_rejected = True
                    break
            if first_guard_rejected:
                break

        if first_guard_rejected:
            raise GuardRejected(self._state, event)

        # 4. Run normal transition
        # 4a. Current state's on_exit
        for h in self._states[self._state].on_exit:
            h(self, Event(self._state, self._state, self._state, event_dict))

        # 4b. Transition's action
        for h in t.action:
            h(self, Event(self._state, self._state, self._state, event_dict))

        # 4c. Set state
        self._state = t.target[0]
        self._history.append((self._state, event, t.target[0]))

        # 4d. Target state's on_enter
        for h in self._states[self._state].on_enter:
            h(self, Event(self._state, self._state, self._state, event_dict))

        # 4e. On transition listeners (in order added)
        for h in self._states[self._state].on_transition:
            h(self, Event(self._state, self._state, self._state, event_dict))

        # 4f. Handle internal transitions (target == source)
        # They still run on_exit and on_enter
        # They run on_action, record history, run listeners
        # They do NOT run on_exit or on_enter of the old state (already done in 4c)
        # Note: The spec says "An internal transition... runs no on_exit or on_enter".
        # But point 4d/4e says "target state's on_enter". If target is source, we already did that.
        # Re-reading point 4e: "target state's on_enter". If target is source, it's the same state.
        # So on_exit/on_enter of the NEW state is called.
        # Does on_exit of the OLD state happen? No, only if target is different.
        # Does on_action happen? Yes.
        # Does on_enter of OLD state happen? No.
        # Does on_enter of NEW state happen? Yes (4d).
        # Does on_exit of NEW state happen? Yes (4c).
        # This matches the logic.

        # 5. Internal transition specifics
        # No on_enter/on_exit for the *change* of state?
        # "An internal transition... runs no on_exit or on_enter and the state stays the same."
        # This implies we skip the "current state's on_exit" and "target state's on_enter" blocks
        # that apply to normal transitions.
        # However, the action still runs.
        # And listeners run.

        # Special case: If target is None, we skip the state change logic entirely.
        if t.target is None:
            # Run action
            for h in t.action:
                h(self, Event(self._state, self._state, self._state, event_dict))
            # Run listeners
            for h in self._states[self._state].on_transition:
                h(self, Event(self._state, self._state, self._state, event_dict))
            # No history append needed as target is self? 
            # Spec says "records history". Usually internal transitions are recorded as well.
            # But since target is source, history entry might be redundant or same.
            # Let's follow the spec strictly: "records history".
            # We should record the event.
            self._history.append((self._state, event, self._state))
            # Note: The spec says "An internal transition... runs no on_exit or on_enter".
            # It doesn't explicitly say it doesn't record history, but it says "the state stays the same".
            # If we record history, we append (self._state, event, self._state).
            # This is consistent.

        # 6. Exception handling
        # Propagate unchanged out of fire if exception comes from guard/action
        # If from on_enter/listener, state has already changed.
        # This logic is implicitly handled by the fact that if an exception happens,
        # the function returns (possibly) with a different state (if on_enter)
        # OR if it's a guard, we don't change state.
        # But the spec says "If it comes from a guard, on_exit or the action, the state and history are unchanged."
        # If it comes from on_enter or listener, "the state has already changed".
        # So we just re-raise the exception.
        try:
            # Re-raise to ensure we don't return a new state
            raise
        except Exception:
            # Re-raise
            raise

    def can_fire(self, event: str, **data: Any) -> bool:
        raise NotImplementedError

    def available_events(self) -> typing.List[str]:
        raise NotImplementedError

    def on_transition(self, listener: Callable[[Machine, Event, str], None]) -> None:
        raise NotImplementedError

    def reset(self) -> None:
        raise NotImplementedError
