"""Parsing, dataclasses, and exception handling."""

from dataclasses import dataclass, field
from typing import Optional, List, Dict, Any, Tuple
from urllib.parse import quote, unquote, parse_qs, urlencode
import base64
import re

from . import HTTPError

# Reason phrases
REASON_PHRASES = {
    200: 'OK',
    201: 'Created',
    204: 'No Content',
    400: 'Bad Request',
    401: 'Unauthorized',
    404: 'Not Found',
    405: 'Method Not Allowed',
    500: 'Internal Server Error',
}


class Headers:
    """Ordered, case-insensitive multi-map of header fields."""

    def __init__(self, pairs: Tuple[str, str] = ()):
        self._data: Dict[str, str] = {}
        for name, value in pairs:
            self._data[name.lower()] = value

    def add(self, name: str, value: str) -> None:
        self._data[name.lower()] = value

    def set(self, name: str, value: str) -> None:
        if name not in self._data:
            self._data[name.lower()] = value
        else:
            del self._data[name.lower()]

    def get(self, name: str, default: Optional[str] = None) -> Optional[str]:
        return self._data.get(name.lower(), default)

    def __getitem__(self, name: str) -> Optional[str]:
        return self._data.get(name.lower())

    def __contains__(self, name: str) -> bool:
        return name.lower() in self._data

    def __len__(self) -> int:
        return len(self._data)

    def items(self) -> List[Tuple[str, str]]:
        return [(k, self._data[k]) for k in self._data]

    def get_all(self, name: str) -> List[str]:
        return [self._data[k] for k in self._data if k.lower() == name.lower()]


@dataclass
class Request:
    """Dataclass representing a parsed HTTP request."""
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, List[str]] = field(default_factory=dict)
    state: Dict[str, Any] = field(default_factory=dict)


    @property
    def query(self) -> Dict[str, List[str]]:
        """Decoded query string parsed by RFC 3986."""
        if not self.query_string:
            return {}
        # Split on &
        parts = self.query_string.split('&')
        result: Dict[str, List[str]] = {}
        for part in parts:
            if not part:
                continue
            # Split at first =
            idx = part.find('=')
            if idx != -1:
                name = part[:idx].strip()
                value = part[idx + 1:].strip()
            else:
                name = part.strip()
                value = ''

            # Validate Name: token chars only
            if not re.match(r'^[A-Za-z0-9!#$%&\'*+\.^_~-]+$', name):
                raise HTTPError('BadRequest', 'Bad Request')
            # Validate Value: percent-encoded or valid UTF-8
            if not re.match(r'^[0-9A-Fa-f]{2}(?:\s|$)*$', value):
                raise HTTPError('BadRequest', 'Bad Request')
            try:
                decoded = value.decode('utf-8')
            except UnicodeDecodeError:
                raise HTTPError('BadRequest', 'Bad Request')
            if name in result:
                result[name].append(decoded)
            else:
                result[name] = [decoded]
        return result


    @property
    def content_type(self) -> Tuple[str, Dict[str, str]]:
        """Media type and parameters (name=value)."""
        if not self.headers:
            return ('', {})
        ct = self.headers.get('content-type', '')
        if not ct:
            return ('', {})

        # Split on ';'
        pieces = ct.split(';')
        media_type = None
        params: Dict[str, str] = {}

        for piece in pieces:
            # Strip leading/trailing whitespace
            piece = piece.strip()
            if not piece:
                continue

            if '=' in piece:
                key, value = piece.split('=', 1)
                # Strip quotes from value
                value = value.strip('"\'')
                # Lower case key
                key = key.lower()
                params[key] = value
            elif piece:
                # No =, skip
                continue

        # If no media type found, default to empty string (per spec: split on ;, first stripped lower, others stripped)
        # Actually spec says: "the value is split on ;; the first piece, stripped and lower-cased, is the media type; every other piece..."
        # If the first piece is just a parameter, media_type is empty.
        # Let's follow spec strictly: if first piece is a parameter, media_type is empty.
        if media_type is None:
            media_type = ''
        return (media_type, params)


    @staticmethod
    def text(s: bytes, charset: Optional[str] = None) -> str:
        """Decodes body with charset or UTF-8."""
        if charset:
            return s.decode(charset)
        return s.decode('utf-8')


    @staticmethod
    def json(obj: Any) -> str:
        """Parses text as JSON."""
        s = Request.text(obj)
        return s


    @staticmethod
    def body_text(request: Request) -> str:
        """Returns body text."""
        return Request.text(request.body)


    @staticmethod
    def body_json(request: Request) -> Any:
        """Parses body as JSON."""
        return Request.json(Request.body_text(request))


    def to_bytes(self) -> bytes:
        """Serializes the response."""
        status = self.method + ' ' + self.version + ' HTTP/1.1'
        reason = REASON_PHRASES.get(self.status, 'Unknown')
        status_line = f"{status} {reason}"
        body = self.body

        # Build header list
        lines = [status_line]
        lines.append('Content-Length: ' + str(len(body)))

        # Add headers in order
        for name, value in self.headers.items():
            lines.append(f'{name}: {value}')

        lines.append('')
        lines.append(body)

