@dataclass
class Response:
    """Dataclass representing a parsed HTTP response."""
    status: int
    headers: Headers = field(default_factory=Headers)
    body: bytes = field(default=b'')


    @staticmethod
    def text(s: str, status: int = 200) -> Response:
        """Encodes string as UTF-8 with Content-Type: text/plain; charset=utf-8."""
        body = s.encode('utf-8')
        return Response(status=status, headers={'Content-Type': 'text/plain; charset=utf-8'}, body=body)


    @staticmethod
    def json(obj: Any, status: int = 200) -> Response:
        """Uses json.dumps with separators, sort_keys, UTF-8, Content-Type: application/json."""
        body = json.dumps(obj, separators=(',', ':'), sort_keys=True).encode('utf-8')
        return Response(status=status, headers={'Content-Type': 'application/json'}, body=body)


    def __init__(self, status: int = 200, headers: Headers = None, body: bytes = b''):
        if headers is None:
            self.headers = Headers()
        self.status = status
        self.headers = headers or Headers()
        self.body = body


    def text(self, s: str, status: int = 200) -> Response:
        """Class method to encode s as UTF-8 with Content-Type: text/plain; charset=utf-8."""
        return Response.text(s, status)


    def json(self, obj: Any, status: int = 200) -> Response:
        """Class method to use json.dumps(obj, separators=(',', ':'), sort_keys=True)"""
        return Response.json(obj, status)


    def to_bytes(self) -> bytes:
        """Serializes the response."""
        if self.headers:
            # Build header string manually to avoid list joining overhead in join
            header_str = ''
            for name, value in self.headers.items():
                header_str += f'{name}: {value}\r\n'
            header_str += 'Content-Length: ' + str(len(self.body)) + '\r\n'
        else:
            header_str = ''

        body_str = self.body
        if self.headers:
            body_str += header_str
        body_str += '\r\n'
        return body_str.encode('utf-8')


@dataclass
class HTTPError(Exception):
    """Base exception for HTTP errors."""
    status: int
    reason: str


@dataclass
class BadRequest(HTTPError):
    """HTTP 400 Bad Request."""
    pass


@dataclass
class NotFound(HTTPError):
    """HTTP 404 Not Found."""
    pass


@dataclass
class MethodNotAllowed(HTTPError):
