from .formula import parse_formula, ErrorValue, evaluate, FormulaError
from .graph import DependencyGraph

class Sheet:
    def __init__(self):
        self._cells: dict[str, str] = {}
        self._deps: DependencyGraph = DependencyGraph()
        self._evaluations = 0

    def set(self, name: str, raw: str) -> List[str]:
        if not isinstance(raw, str):
            raise TypeError("raw must be a str")

        self._normalize_name(name)
        self._normalize_name(raw)

        # Parse formula
        try:
            _, refs = parse_formula(raw)
        except FormulaError:
            raise FormulaError(f"Formula '{raw}' is invalid")

        # Determine value
        value = self._resolve_refs(refs)
        self._set_cell(name, value)

        # Identify affected cells
        affected = self._set_dependents(name, refs)
        affected.add(name)

        return list(affected)

    def _normalize_name(self, s: str):
        """Convert name to upper case and ensure valid format."""
        s = s.strip().upper()
        if not s:
            raise ValueError("Empty name")

        # Check format: one letter followed by digits (1-999)
        if len(s) < 2:
            raise ValueError(f"Name must contain at least one letter and digits")
        if s[0].isdigit():
            raise ValueError(f"Name must start with a letter")
        if s[0].isalpha() and len(s) > 1:
            if s[1].isdigit():
                if len(s) > 2:
                    raise ValueError(f"Row must not exceed 999")

        return s

    def get(self, name: str) -> Optional[str]:
        self._normalize_name(name)
        return self._cells.get(name)

    def raw(self, name: str) -> str:
        self._normalize_name(name)
        return self._cells.get(name, '')

    def cells(self) -> List[str]:
        """Return non-empty cells in row-major order."""
        cells = []
        for row in range(1, 1000):
            for col in 'ABCDEFGHI':
                name = f"{col}{row}"
                if name in self._cells and self._cells[name]:
                    cells.append(name)
        return cells

    def evaluations(self) -> int:
        return self._evaluations

    def _resolve_refs(self, refs: Set[str]) -> Optional[str]:
        """Resolve a formula reference list into a single value."""
        if not refs:
            return None

        # Get values of referenced cells
        values = []
        for ref in refs:
            val = self._cells.get(ref)
            values.append(val)

        # Evaluate the formula
        return evaluate(values, self._deps)

    def _set_cell(self, name: str, value: Any):
        self._cells[name] = value

    def _set_dependents(self, cell: str, refs: Set[str]) -> Set[str]:
        """Return all cells whose value might change due to this cell."""
        # Start with the cell itself
        affected = {cell}

        # Recursively add dependents of referenced cells
        for ref in refs:
            if ref in self._deps._nodes:
                affected.update(self._deps.dependents(ref))
            elif ref in self._deps._cells:
                # It's a non-cell value, just add it
                pass

        # Add self to all_dependents if on a cycle
        if self._deps._nodes and self._deps.all_dependents(cell):
            affected.update(self._deps.all_dependents(cell))

        return affected
