        self._edges: typing_Set[str] = set()  # cell -> [precedes]

    def set_dependencies(self, cell: str, precedents: typing_Set[str]):
        if cell not in self._nodes:
            self._nodes.add(cell)
        self._edges[cell] = precedents

    def precedents(self, cell: str) -> typing_Set[str]:
        return self._edges.get(cell, set())

    def dependents(self, cell: str) -> typing_Set[str]:
        # All nodes reachable from cell
        visited = {cell}
        queue = list(self._edges.get(cell, set()))
        while queue:
            prev = queue.pop(0)
            for dep in self._edges.get(prev, set()):
                if dep not in visited:
                    visited.add(dep)
                    queue.append(dep)
        return visited

    def all_dependents(self, cell: str) -> typing_Set[str]:
        """Includes self if on a cycle."""
        descendants = self.dependents(cell)
        if cell in self._nodes:
            return descendants.union({cell})
        else:
            return descendants

    def cycle_cells(self) -> typing_Set[str]:
        """Returns cells that are part of a cycle (refer to themselves directly or indirectly)."""
        # BFS from each node to see if we can reach back to itself
        visited = set()
        cycle_nodes = set()
        for node in self._nodes:
            if node in self._edges:
                if self._dfs(node, set(), visited):
                    cycle_nodes.add(node)
        return cycle_nodes

    def _dfs(self, start: str, path: typing_Set[str], visited: typing_Set[str]) -> bool:
        if start in visited:
            return False
        visited.add(start)

        if start in self._edges:
            for dep in self._edges[start]:
                if self._dfs(dep, path.union({start}), visited):
                    return True

        return False
