import re
from abc import ABC, abstractmethod
from typing import Any, List, Optional, Set

class FormulaError(ValueError):
    """Base class for formula parsing errors."""
    pass

class ErrorValue(str):
    """A subclass of str representing an error value."""
    pass

# Global error values
ERROR = ErrorValue("#ERROR!")
CYCLE = ErrorValue("#CYCLE!")
DIV_ZERO = ErrorValue("#DIV/0!")
VALUE = ErrorValue("#VALUE!")
REF = ErrorValue("#REF!")

class FormulaError(ValueError):
    """Raised when parsing a formula fails."""
    pass

# Global error value instances
ERROR_VALUE = ERROR
CYCLE_VALUE = CYCLE
DIV_ZERO_VALUE = DIV_ZERO
VALUE_VALUE = VALUE
REF_VALUE = REF

def parse_formula(source: str) -> tuple[dict[str, Any], Set[str]]:
    """
    Parses source text after '=' and returns a syntax tree (dict of identifiers -> values).
    Returns empty dict if parsing fails.
    Raises FormulaError if parsing fails.
    """
    source = source.strip()
    if not source.startswith('='):
        raise FormulaError("Formula must start with '='")

    formula = source[1:].strip()

    if not formula:
        return {}, set()

    # Remove trailing parenthesis if present and empty
    if formula.endswith(')'):
        formula = formula[:-1]

    if not formula:
        raise FormulaError("Empty formula")

    tokens = _tokenize(formula)
    tree = _build_tree(tokens)

    if tree is None:
        raise FormulaError("Incomplete expression")

    # Collect references
    refs = set()
    for node in tree:
        if isinstance(node, ReferenceNode):
            refs.add(node.name)

    return tree, refs

def _tokenize(formula: str) -> list[str]:
    """Tokenize formula into tokens."""
    tokens = []
    i = 0
    n = len(formula)

    while i < n:
        char = formula[i]

        # Handle unary minus/plus (bind tighter than binary, handled in build)
        if char in ('+', '-'):
            tokens.append(char)
            i += 1
            continue

        # Number
        if char.isdigit():
            num_str = formula[i:]
            while i < n and formula[i].isdigit():
                i += 1
            tokens.append(num_str)
            continue

        # Reference (letters followed by optional digits)
        if char.isalpha():
            j = i
            while j < n and formula[j].isalnum():
                j += 1
            tokens.append(formula[i:j])
            continue

        # Operators and delimiters
        if char in ('+', '-', '*', '/', '(', ')'):
            tokens.append(char)
            continue

        # Unknown character
        raise FormulaError(f"Invalid character in formula: '{char}'")

    raise FormulaError("Unterminated expression")

class BinOpNode(float):
    """A float subclass representing binary operators (+, -, *, /)."""
    pass

class UnaryOperator(float):
    """A float subclass representing unary signs (+, -)."""
    pass

class Node(ABC):
    @abstractmethod
    def value(self) -> Any:
        pass

    @abstractmethod
    def name(self) -> str:
        pass

    @abstractmethod
    def type(self) -> str:
        pass

class NumberNode(Node):
    def __init__(self, val: float):
        self.val = val
        self.type = "number"
    def value(self) -> Any:
        if isinstance(self.val, float):
            return self.val
        return self.val
    def name(self) -> str:
        return self.val
    def type(self) -> str:
        return "number"

class ReferenceNode(Node):
    def __init__(self, name: str):
        self.name = name.upper()
        self.type = "ref"
    def value(self) -> Any:
        return None  # Will be resolved by the caller (evaluation)
    def name(self) -> str:
        return self.name
    def type(self) -> str:
        return "ref"

class CallNode(Node):
    def __init__(self, name: str, args: List[Node]):
        self.name = name.upper()
        self.args = args
        self.type = "call"
    def value(self) -> Any:
        if self.type == "call":
            return self._eval_args()
        return self._eval_single()
    def name(self) -> str:
        return self.name
    def type(self) -> str:
        return "call"

    def _eval_args(self) -> Any:
        """Evaluate range arguments and collect numbers."""
        numbers = []
        first_error = None

        # Process arguments left to right
        for arg in self.args:
            if isinstance(arg, RangeNode):
                # Range evaluation
                vals = self._eval_range(arg)
                if vals is not None:
                    numbers.extend(vals)
                    # If we hit an error here, it's the first error for the call
                    if first_error is None:
                        first_error = ERROR_VALUE
                else:
                    # No valid numbers found from range, return error
                    first_error = ERROR_VALUE
            elif isinstance(arg, ReferenceNode):
                # Single cell reference (or empty range logic)
                val = self._eval_range(arg)
                if val is not None:
                    numbers.extend([val])
                else:
                    # Empty cell or text
                    first_error = VALUE_VALUE
            else:
                # Other argument, evaluate as expression
                val = self._eval_single()
                if val is not None:
                    numbers.append(val)
                elif isinstance(val, ErrorValue):
                    first_error = val
                else:
                    first_error = VALUE_VALUE

        if first_error is None:
            # No numbers found at all
            first_error = ERROR_VALUE

        return first_error if first_error is not None else self._calculate(numbers)

    def _eval_single(self) -> Any:
        """Evaluate a single reference or number."""
        node = self._find_node()
        if node is None:
            return None
        return node.value()

    def _find_node(self) -> Optional[Node]:
        """Find the next node in the expression tree."""
        if len(self.args) == 0:
            return None
        for i, arg in enumerate(self.args):
            if isinstance(arg, RangeNode) or isinstance(arg, CallNode):
                return arg
        # Reached end of arguments or empty expression
        return None

    def _eval_range(self, node: RangeNode) -> Optional[List[Any]]:
        """Evaluate a range defined by two cells."""
        r1 = node.r1
        r2 = node.r2
        if r1 == r2:
            # Single cell
            cell_val = self._get_cell_value(r1)
            if cell_val is not None:
                return [cell_val]
            return None

        # Two cells: find all cells in range [min_row, min_col] to [max_row, max_col]
        min_row = min(r1.row, r2.row)
        min_col = min(r1.col, r2.col)
        max_row = max(r1.row, r2.row)
        max_col = max(r1.col, r2.col)

        values = []
        for row in range(min_row, max_row + 1):
            for col in range(min_col, max_col + 1):
                cell_name = f"{chr(ord('A') + (col - 1))}{row}"
                cell_val = self._get_cell_value(cell_name)
                if cell_val is not None:
                    values.append(cell_val)
        return values if values else None

    def _get_cell_value(self, name: str) -> Optional[Any]:
        """Get value from a cell."""
        if name in self._cells:
            return self._cells[name]
        return None

class RangeNode(Node):
    def __init__(self, r1: str, r2: str, type: str):
        self.r1 = r1
        self.r2 = r2
        self.type = type
        self.row1 = None
        self.col1 = None
        self.row2 = None
        self.col2 = None

    def value(self) -> Optional[List[Any]]:
        return self._eval_range()

    def name(self) -> str:
        return f"{self.r1}:{self.r2}"

    def type(self) -> str:
        return "range"

    def _eval_range(self) -> Optional[List[Any]]:
        r1 = self.r1
        r2 = self.r2
        if r1 == r2:
            cell_val = self._get_cell_value(r1)
            if cell_val is not None:
                return [cell_val]
            return None

        # Parse corners
        for i, c in enumerate('ABC'):
            for j, digit in enumerate('123456789'):
                if c == r1[0] and j == 0:
                    self.row1 = i
                    self.col1 = int(digit)
                elif c == r2[0] and j == 0:
                    self.row2 = i
                    self.col2 = int(digit)
        # Swap if needed? The logic assumes r1 is top-left, r2 is bottom-right
        # Actually, let's just use min/max.
        # Re-parse to find min/max properly
        row1_val = float('inf')
        col1_val = float('inf')
        row2_val = float('-inf')
        col2_val = float('-inf')

        # Check r1
        for i, c in enumerate('ABC'):
            for j, digit in enumerate('123456789'):
                if c == r1[0] and j == 0:
                    row1_val = i
                    col1_val = int(digit)
                elif c == r2[0] and j == 0:
                    row2_val = i
                    col2_val = int(digit)

        # Determine bounds
        min_r = min(row1_val, row2_val)
        max_r = max(row1_val, row2_val)
        min_c = min(col1_val, col2_val)
        max_c = max(col1_val, col2_val)

        values = []
        for row in range(min_r, max_r + 1):
            for col in range(min_c, max_c + 1):
                cell_name = f"{chr(ord('A') + (col - 1))}{row}"
                cell_val = self._get_cell_value(cell_name)
                if cell_val is not None:
                    values.append(cell_val)

        return values if values else None

class Tree:
    def __init__(self, value: Any, name: str, type: str):
        self.value = value
        self.name = name
        self.type = type
    def value(self) -> Any:
        return self.value
    def name(self) -> str:
        return self.name
    def type(self) -> str:
        return self.type

def _build_tree(tokens: list[str]) -> Tree | None:
    """Build a tree from tokens."""
    if not tokens:
        return None

    # Start with a number or reference
    first = tokens[0]
    if first == '(' and len(tokens) >= 2 and tokens[1] == ')':
        # ( ... )
        return Tree(None, None, "expr")
    elif first.isalpha() or (first.isdigit()):
        # Number or Ref
        tree = Tree(float(first), first, "unary")
        for op in tokens[1:]:
            if op in ('+', '-'):
                tree = UnaryOperator(op, tree, None)
            elif op in ('*', '/'):
                tree = BinOpNode(op, tree, None)
            else:
                tree = tree.op(op, None, None)
        return tree
    else:
        # It must be an operator
        raise FormulaError("Unexpected token in expression")
