# games/tictactoe.py
from enum import Enum
from dataclasses import dataclass
import re

class Cell:
    EMPTY = '.'
    X = 'X'
    O = 'O'

    def __init__(self, char):
        self.char = char

    def __repr__(self):
        return self.char

@dataclass
class TicTacToe:
    """
    A state for Tic-Tac-Toe.
    """
    board: list[Cell]

    def __post_init__(self):
        if len(self.board) != 9:
            raise ValueError(f"Board length must be 9, got {len(self.board)}")
        counts = [0, 0]  # X and O
        for cell in self.board:
            if cell.char == 'X':
                counts[0] += 1
            elif cell.char == 'O':
                counts[1] += 1
            elif cell.char != '.':
                raise ValueError(f"Invalid character in board: {cell.char}")
            if counts[0] != counts[1] + 1:
                raise ValueError(f"Invalid counts: X={counts[0]}, O={counts[1]}")

    @staticmethod
    def from_moves(moves):
        """
        Plays the given squares in order from an empty board.
        Raises ValueError at the first illegal move.
        """
        board = ['.' for _ in range(9)]

        for move in moves:
            # Convert string index to 0-8 integer
            col = int(move)

            if col < 0 or col > 8:
                raise ValueError(f"Move out of bounds: {move}")
            if board[col] != '.':
                raise ValueError(f"Move {move} already taken")
            board[col] = Cell('X')

        return TicTacToe(board)

    def winner(self) -> str | None:
        rows = [
            [self.board[i], self.board[i+1], self.board[i+2]],
            [self.board[3], self.board[4], self.board[5]],
            [self.board[6], self.board[7], self.board[8]],
            [self.board[0], self.board[1], self.board[2]],
            [self.board[4], self.board[5], self.board[6]],
            [self.board[2], self.board[4], self.board[6]],
            [self.board[0], self.board[2], self.board[4]],
            [self.board[8], self.board[4], self.board[0]],
        ]

        for row in rows:
            if row[0].char == row[1].char == row[2].char:
                return row[0].char

        return None

    def is_over(self) -> bool:
        return self.winner() is not None or len(self.board) == 9

    def str(self):
        return '\n'.join(cell.char for cell in self.board)
