# games/connect4.py
from dataclasses import dataclass
from enum import Enum

class Cell(Enum):
    EMPTY = '.'
    X = 'X'
    O = 'O'

    def __repr__(self):
        return self.value

@dataclass
class ConnectFour:
    columns: int
    rows: int

    def __post_init__(self):
        if self.columns < 1:
            raise ValueError("Columns must be >= 1")
        if self.rows < 1:
            raise ValueError("Rows must be >= 1")

    @staticmethod
    def from_moves(moves, columns=7, rows=6):
        """
        Plays the given columns in order from an empty board.
        Raises ValueError at the first illegal move.
        """
        board = [[Cell(EMPTY) for _ in range(rows)] for _ in range(columns)]

        for move in moves:
            col = int(move)
            row = 0
            while True:
                # Check bounds
                if col >= 0 and col < columns:
                    if row >= rows:
                        raise ValueError(f"Move {move} out of bounds")
                    # Check if already taken
                    if board[col][row] != Cell(EMPTY):
                        raise ValueError(f"Move {move} already taken")
                    break

                # Fall down
                board[col][row] = Cell('X')
                row += 1
                if row >= rows:
                    break

        # Check win conditions
        win = False
        for c in range(columns):
            for r in range(rows):
                if board[c][r] != Cell(EMPTY):
                    if board[c][r].char == 'X' and c < 3: # Horizontal
                        if board[c][r+1].char == 'X' and c+1 < 3:
