def play_game(state, agents: dict) -> tuple[object, list]:
    """
    Asks agents for moves until game over.
    Returns final state and list of moves.
    Raises ValueError if an illegal move is attempted.
    """
    if isinstance(state, TicTacToe):
        state.player = 'X'
        state.moves = state.moves()
    else:
        state.player = state.player

    moves_played = []
    while not state.is_over():
