            if state.player in agents:
                move = agents[state.player](state)
                state = state.play(move)
                moves_played.append(move)
            else:
                raise ValueError(f"Agent {state.player} not found")
        except ValueError as e:
            raise e

    return state, moves_played

# Game Tree Search Logic
def evaluate(state):
    """
    ConnectFour Heuristic.
    Scores for state.player.
    """
    if state.player == 'O':
        total = 0
        # Horizontal
        for c in range(3):
            for r in range(2):
                if state.cell(c, r).char == 'O' and state.cell(c, r+1).char == 'O':
                    if state.cell(c, r+2).char == 'O':
