                    if state.cell(c+2, r+2).char == 'O':
                        total += 9
                if state.cell(c, r).char == 'O' and state.cell(c+1, r+1).char == 'O':
                    total += 4
                if state.cell(c, r).char == 'O' and state.cell(c+1, r+1).char == 'O':
