def _window(state, c, r):
    """
    Helper to check a window of 4 cells.
    Returns tuple: (is_valid, count, is_winner)
    Window: Horizontal (r, c), (r, c+1), (r, c+2), (r, c+3)
    Vertical: r, r+1, r+2, r+3
    Diagonals: (r-1, c-1), (r-1, c), (r-1, c+1), (r, c-1), (r, c), (r, c+1), (r, c+2), (r+1, c-1), (r+1, c), (r+1, c+1)
    """
    cells = [
        (r, c), (r, c+1), (r, c+2), (r, c+3),
        (r, c), (r, c+1), (r, c+2), (r+1, c), (r+1, c+1), (r+1, c+2),
        (r-1, c-1), (r-1, c), (r-1, c+1), (r, c-1), (r, c), (r, c+1), (r, c+2), (r+1, c-1), (r+1, c), (r+1, c+1)
    ]

    # Filter valid cells in window
    valid = [(sr, sc) for sr, sc in cells if 0 <= sr < state.rows and 0 <= sc < state.columns]

    # Check counts
    if len(valid) < 4:
        return False, 0, False

    # Count pieces for state.player
    player_count = sum(1 for (sr, sc) in valid if state.cell(sr, sc).char == state.player)

    if state.player == 'O':
        if len(valid) == 4:
            return False, 4, False
        if player_count == 4:
            return True, player_count, False
        if player_count == 3:
            return True, player_count, False
        if player_count == 2:
            return True, player_count, False
        if player_count == 1:
            return True, player_count, False
        if player_count == 0:
            return False, 0, False
    else:
        if len(valid) == 4:
            return False, 4, False
        if player_count == 4:
            return False, 4, True
        if player_count == 3:
            return False, 3, True
        if player_count == 2:
            return False, 2, True
        if player_count == 1:
            return False, 1, True
        if player_count == 0:
            return False, 0, False

    # Check winner
    winner = False
    for (sr, sc) in valid:
        if state.cell(sr, sc).char == state.player:
            winner = True
            break
    return winner, player_count, winner

def search(state, depth=None, evaluate=None):
    """
    Negamax search with alpha-beta pruning.
    Returns SearchResult with score, move, nodes.
    """
    moves = state.moves()
    if not moves:
        # Game over
        if evaluate:
            return SearchResult(score=evaluate(state), move=None, nodes=1)
        else:
            return SearchResult(score=0, move=None, nodes=1)

    best_score = float('-inf')
    best_moves = []
    alpha = float('-inf')
    beta = float('inf')
    nodes = 0
    moves_index = 0
    last_eval = None

    for move in moves:
        nodes += 1
        new_state = state.play(move)

        if last_eval is not None:
            if last_eval > alpha:
                continue
            if last_eval < beta:
                continue

        # If game over in this branch, score it now
        if new_state.is_over():
            if evaluate:
                # Score for the player to move in new_state
                if new_state.player == 'X':
                    val = -(1000 - new_state.ply)
                else:
                    val = 0
            else:
                val = 0
            if val > best_score:
                best_score = val
                best_moves = [move]
            elif val == best_score:
                best_moves.append(move)
            nodes += 1
            continue

        if evaluate:
            # Recursive step
            if depth is not None:
                next_depth = depth - 1
                if next_depth < 0:
                    next_eval = evaluate(new_state)
                else:
                    next_eval = search(new_state, next_depth, evaluate)
                if next_eval is not None:
                    # Alpha beta pruning
                    if next_eval > alpha:
                        last_eval = next_eval
                        if last_eval > best_score:
                            best_score = last_eval
                            best_moves = [move]
                            alpha = last_eval
                            if best_moves:
