                    if last_eval > best_score:
                        best_score = last_eval
                        best_moves = [move]
                        alpha = last_eval
                        if best_moves:
                            nodes += 1
                        continue
                    elif best_moves and last_eval < beta:
                        beta = last_eval
                        continue
        else:
            # No evaluate function provided, score is 0
            val = 0
            if val > best_score:
                best_score = val
                best_moves = [move]
                alpha = val
                if best_moves:
                    nodes += 1
                continue
            elif best_moves and val < beta:
                beta = val
                continue

        # Check terminal condition for this specific move
        if new_state.is_over():
            if evaluate:
                if new_state.player == 'X':
                    val = -(1000 - new_state.ply)
                else:
                    val = 0
            else:
                val = 0
            if val > best_score:
                best_score = val
                best_moves = [move]
            elif val == best_score:
                best_moves.append(move)
            nodes += 1
            continue

        # Continue to children
        children = search(new_state, depth, evaluate)
        if children.score > best_score:
            best_score = children.score
            best_moves = [move]
            alpha = best_score
            nodes = children.nodes
        elif children.score == best_score:
            best_moves.append(move)
            nodes += children.nodes
        else:
            if children.score < beta:
                beta = children.score
            if best_moves and children.score < beta:
                break

    if not best_moves:
