# rx/parse.py
import dataclasses
from dataclasses import dataclass, field
from typing import Tuple, List, Union, Optional, Any

@dataclass
class Empty:
    """Matches the empty string."""

@dataclass
class Literal:
    char: str

@dataclass
class AnyChar:
    """Matches any single character except newline."""

@dataclass
class CharClass:
    items: Tuple[Tuple[str, str], ...] = field(default_factory=lambda: ())
    negated: bool = False

    def __post_init__(self):
        if not self.items:
            raise ValueError("Empty character class")

        # Validate range
        for low, high in self.items:
            if not isinstance(low, str):
                raise ValueError(f"Class item must be a char, got {type(low)}")
            if not isinstance(high, str):
                raise ValueError(f"Class item must be a char, got {type(high)}")
            if low > high:
                raise ValueError(f"Invalid range: {low} > {high}")

    def __eq__(self, other):
        if not isinstance(other, CharClass):
            return False
        if self.negated != other.negated:
            return False
        return self.items == other.items

@dataclass
class Group:
    node: Any

@dataclass
class Concat:
    items: Tuple[Any, ...] = field(default_factory=lambda: ())

@dataclass
class Star:
    node: Any

@dataclass
class Plus:
    node: Any

@dataclass
class Optional:
    node: Any

@dataclass
class Alt:
    options: Tuple[Any, ...] = field(default_factory=lambda: ())

@dataclass
class RegexError(ValueError):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position

    def __eq__(self, other):
        return isinstance(other, RegexError) and self.message == other.message and self.position == other.position

    def __str__(self):
        return f"RegexError({self.message!r}, position={self.position})"

def parse(pattern: str) -> Any:
    """
    Parses a pattern string into an AST node.
    Raises RegexError on parse errors.
    """
    if not pattern:
        return Empty()

    # Helper to tokenize
    def _tokenize() -> List[Any]:
        i = 0
        tokens = []
        while i < len(pattern):
            ch = pattern[i]
            if ch == ".":
                tokens.append(AnyChar())
            elif ch == "|":
                i += 1
                if i >= len(pattern):
                    raise RegexError("Unexpected '|' at end of pattern", i)
                tokens.append(Alt((_tokenize(),)))
                i += 1
            elif ch == "(":
                i += 1
                if i >= len(pattern):
                    raise RegexError("Unbalanced '(', missing closing ')'", i)
                # Find matching ')'
                depth = 1
                j = i + 1
                while j < len(pattern) and depth > 0:
                    if pattern[j] == "(":
                        depth += 1
                    elif pattern[j] == ")":
                        depth -= 1
                        if depth == 0:
                            break
                    j += 1
                if depth != 0:
                    raise RegexError("Unbalanced '(', unclosed at index", j)
                tokens.append(Group(Concat(_tokenize())))
                i = j
            elif ch == "[":
                i += 1
                # Find ]
                j = i
                while j < len(pattern) and pattern[j] != "]":
                    j += 1
                if j < len(pattern):
                    i = j
                else:
                    raise RegexError("Unbalanced '[', missing closing ']'", i)

                class_items = []
                negated = False

                if pattern[i] == "^":
                    negated = True
                    i += 1
                if i < len(pattern):
                    ch = pattern[i]
                    if ch == "\\":
                        i += 1
                        # Skip backslash escape
                        while i < len(pattern) and pattern[i] == "\\":
                            i += 1
                    elif ch == "-":
                        # Literal if first or last item
                        if not class_items:
                            class_items.append((ch, ch))
                        else:
                            i += 1
                        # Check if next item exists and is escaped (unlikely but safe check)
                        if i < len(pattern) and pattern[i] != "\\":
                            i += 1
                            # Skip to next item
                            while i < len(pattern) and pattern[i] != "-":
                                i += 1
                        if i < len(pattern) and pattern[i] == "-":
                            i += 1
                    else:
                        # Single char or range
                        if i + 1 < len(pattern) and pattern[i+1] != "\\":
                            # Check next char is escaped
                            if i + 1 < len(pattern) and pattern[i+1] == "\\":
                                i += 1
                            class_items.append((ch, pattern[i+1]))
                            i += 2
                        else:
                            i += 1
                else:
                    # Empty class
                    raise RegexError("Empty character class", i)

                if not class_items:
                    raise RegexError("Empty character class", i)

                tokens.append(CharClass(class_items, negated))
            elif ch == "+":
                i += 1
                if i >= len(pattern):
                    raise RegexError("Unexpected '+' at end of pattern", i)
                tokens.append(Plus(Concat(_tokenize())))
                i += 1
            elif ch == "*":
                i += 1
                if i >= len(pattern):
                    raise RegexError("Unexpected '*' at end of pattern", i)
                tokens.append(Star(Concat(_tokenize())))
                i += 1
            elif ch == "?":
                i += 1
                if i >= len(pattern):
                    raise RegexError("Unexpected '?' at end of pattern", i)
                tokens.append(Optional(Concat(_tokenize())))
                i += 1
            elif ch == "\\" and i + 1 < len(pattern) and pattern[i+1] != "\\":
                i += 2
            else:
                # Literal
                tokens.append(Literal(ch))
                i += 1

        return tokens

    def _parse_node(tokens: List[Any]) -> Any:
        if not tokens:
            return Empty()
        if len(tokens) == 1:
            return tokens[0]
        if tokens[0] == Literal:
            return Literal(tokens[0].char)
        elif tokens[0] == AnyChar:
            return AnyChar()
        elif tokens[0] == CharClass:
            return CharClass(tokens[0].items, tokens[0].negated)
        elif tokens[0] == Group:
            return Group(_parse_node(tokens[1:]))
        elif tokens[0] == Concat:
            return Concat(_parse_node(t) for t in tokens[1:])
        elif tokens[0] == Star:
            return Star(_parse_node(tokens[1:]))
        elif tokens[0] == Plus:
            return Plus(_parse_node(tokens[1:]))
        elif tokens[0] == Optional:
            return Optional(_parse_node(tokens[1:]))
        elif tokens[0] == Alt:
            return Alt(_parse_node(t) for t in tokens[1:])
        else:
            raise RegexError("Unknown token type", 0)

    try:
        tokens = _tokenize()
        return _parse_node(tokens)
    except RegexError as e:
        raise RegexError(str(e), e.position)
