# rx/nfa.py
import dataclasses
from typing import List, Union, Optional, Tuple

from .parse import (
    Empty, Literal, AnyChar, CharClass, Concat, Star, Plus, Optional, Alt, RegexError
)

# Thompson NFA construction helpers
def _concat_nfa(tokens: List[Any]) -> "NFA":
    """Constructs an NFA for a Concat node."""
    if not tokens:
        raise RegexError("Empty Concat", 0)
    return Concat(
        _nfa_node(t) for t in tokens[1:] if t not in (Star, Plus, Optional, Group, Alt)
    )

def _star_nfa(node: Any) -> "NFA":
    """Constructs a Star NFA from a node."""
    return Star(_nfa_node(node))

def _plus_nfa(node: Any) -> "NFA":
    """Constructs a Plus NFA from a node."""
    return Plus(_nfa_node(node))

def _optional_nfa(node: Any) -> "NFA":
    """Constructs an Optional NFA from a node."""
    return Optional(_nfa_node(node))

def _alt_nfa(options: List[Any]) -> "NFA":
    """Constructs an Alt NFA from a list of options."""
    if not options:
        raise RegexError("Empty Alt", 0)
    return Alt(
        _nfa_node(t) for t in options[1:] if t not in (Star, Plus, Optional, Group, Alt)
    )

def _group_nfa(node: Any) -> "NFA":
    """Constructs a Group NFA from a node."""
    return Group(_nfa_node(node))

def _nfa_node(node: Any) -> "NFA":
    """Base NFA constructor for a single node."""
    if isinstance(node, Concat):
        return Concat._nfa_node(node)
    if isinstance(node, Star):
        return Star._nfa_node(node)
    if isinstance(node, Plus):
        return Plus._nfa_node(node)
    if isinstance(node, Optional):
        return Optional._nfa_node(node)
    if isinstance(node, Alt):
        return Alt._nfa_node(node)
    if isinstance(node, Group):
        return Group._nfa_node(node)
    if isinstance(node, Literal):
        return Literal._nfa_node(node)
    if isinstance(node, AnyChar):
        return AnyChar._nfa_node(node)
    if isinstance(node, CharClass):
        return CharClass._nfa_node(node)
    raise RegexError("Unknown NFA node type", 0)

@dataclasses.dataclass
class NFA:
    """
    Thompson NFA for regex matching.

    State representation:
    - int: regular state index
    - tuple: epsilon state index (tuple of ints)

    Attributes:
        states: list of states
        start: index of initial state
        accept: boolean flag for accepting state
        transitions: dict {state_id: set of {char: next_state}}
    """
    states: List[Tuple] = dataclasses.field(default_factory=list)
    start: int = -1
    accept: bool = False
    transitions: dict = dataclasses.field(default_factory=dict)

    def __post_init__(self):
        if not self.states:
            self._init()

    def _init(self):
        # Initialize regular states as empty tuples
        self.states = [(0,)] * len(self.states) + [(1,)]
        # Add epsilon state
        self.states.append((1,))

        # Build epsilon transitions
        self.transitions = {0: set(self.states[1:]), 1: set()}

    def add_transition(self, from_state: int, char: str, to_state: int):
        if char == ".":
            to_state = self.states[1:] # Any char except newline
        else:
            to_state = to_state + 1 # Next state index

        if from_state in self.transitions:
            self.transitions[from_state].add((char, to_state))
        else:
            self.transitions[from_state] = set()
            self.transitions[from_state].add((char, to_state))

    def match(self, text: str) -> bool:
        """
        Simulates the NFA on text.
        Returns True if the whole text matches.
        Time complexity: O(|text| * |states|)
        """
        if not text:
            return self.accept

        pos = 0
        while pos < len(text):
            state = 0
            while state != -1 and pos < len(text):
                char = text[pos]

                # Epsilon transitions
                state, epsilon = self.states[state]
                if epsilon:
                    state = epsilon

                # Follow transitions
                if char in self.transitions[state]:
                    state = self.transitions[state][char][0]
                else:
                    break

            # Check accept
            if state == self.accept:
                return True

            pos += 1

        return False

    def search(self, text: str, start: int = 0) -> Optional[Tuple[int, int]]:
        """
        Returns the leftmost match of the longest length starting at or after start.
        Returns (i, j) where (i, j] is the match.
        """
        if not text:
            return None

        if start >= len(text):
            return None

        # First, find all matching positions
        matches = []
        for i in range(len(text) + 1): # +1 to allow empty match
            if self.match(text[i:]):
                matches.append(i)

        if not matches:
            return None

        # Sort by start position
        matches.sort(key=lambda x: (x, -len(text))) # Longest first

        # Return first one
        return (matches[0], matches[0])

    def findall(self, text: str) -> List[str]:
        """
        Returns list of matched substrings.
        Scans from position 0.
        Empty match counts.
        """
        results = []
        pos = 0

        while True:
            # Skip empty matches
            if self.match(text[pos:]):
                pos = pos + 1
                continue

            # Find start
            start = self.search(text, pos)
            if start is None:
                break

            # Find end
            end = start + self.search(text, start + 1)
            if end is None:
                break

            results.append(text[start:end])

            # Move past the match
            pos = end + 1

        return results
