import sys
import argparse
from .parse import parse, RegexError
from .nfa import NFA, match, search, findall, RegexError as NFARegexError

def main():
    parser = argparse.ArgumentParser(description="Small Regex Engine")
    subparsers = parser.add_subparsers(dest="command", help="Commands")

    # Parse command
    subparsers.add_parser("parse", help="Parse a pattern")

    # Search command
    subparsers.add_parser("search", help="Search for matches")

    # Findall command
    subparsers.add_parser("findall", help="Find all matches")

    # Test command
    subparsers.add_parser("test", help="Run a test case")

    args = parser.parse_args()

    if args.command == "parse":
        try:
            pattern = args.pattern
            ast = parse(pattern)
            print("Pattern parsed successfully:")
            print(ast)
        except RegexError as e:
            print(f"Error: {e}")

    elif args.command == "search":
        try:
            pattern = args.pattern
            text = args.text or ""
            start = args.start or 0
            result = search(pattern, text, start)
            if result:
                print(f"Match found at {result}: {text[result[0]:result[1]]}")
            else:
                print("No match found")
        except RegexError as e:
            print(f"Error: {e}")

    elif args.command == "findall":
        try:
            pattern = args.pattern
            text = args.text or ""
            results = findall(pattern, text)
            if results:
                print("Matches:")
                for r in results:
                    print(f"  {r}")
            else:
                print("No matches found")
        except RegexError as e:
            print(f"Error: {e}")

    elif args.command == "test":
        cases = args.cases or []
        for case in cases:
            case_name, pattern, text = case
            try:
                ast = parse(pattern)
                print(f"Testing {case_name}: {pattern} on '{text}'")
                matches = findall(ast, text)
                if matches:
                    print(f"  Matches: {matches}")
                else:
                    print(f"  No matches")
            except RegexError as e:
                print(f"  Error: {e}")

if __name__ == "__main__":
    main()
