from dataclasses import dataclass, field
from typing import Dict, List, Set, Optional
from adventure import DIRECTIONS
import json

@dataclass
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, str] = field(default_factory=dict)
    items: List[str] = field(default_factory=list)

@dataclass
class Item:
    id: str
    name: str
    description: str
    portable: bool = True

class WorldError(ValueError):
    """Base exception for World errors."""
    pass

def from_dict(data: Dict) -> World:
    """Build a World from a dict."""
    # Check start
    if "start" not in data:
        raise WorldError("World missing 'start'")

    start = data["start"]
    if start not in data["rooms"]:
        raise WorldError(f"Start room '{start}' not found")

    rooms = data["rooms"]
    items = data.get("items", {})

    # Validate room existence and fields
    valid_dirs = set(DIRECTIONS)
    room_map = {r.id: r for r in rooms.values()}

    def validate_room(room_id: str, room: Room) -> None:
        if room_id not in room_map:
            raise WorldError(f"Room '{room_id}' not found")

        # Check name/description
        if not room["name"] or not room["description"]:
            raise WorldError(f"Room '{room_id}' missing 'name' or 'description'")

        # Check exits
        for dir_str, next_id in room["exits"].items():
            if dir_str.lower() not in valid_dirs:
                raise WorldError(f"Room '{room_id}' has invalid exit direction '{dir_str}'")
            if next_id not in room_map:
                raise WorldError(f"Room '{room_id}' exits to unknown room '{next_id}'")

        # Check items
        for item_id in room["items"]:
            if item_id not in items:
                raise WorldError(f"Room '{room_id}' lists unknown item '{item_id}'")

    # Process rooms
    for room_id, room_data in rooms.items():
        validate_room(room_id, Room.from_dict(room_data))

    # Process items
    for room_id, room in room_map.items():
        if room_id in items:
            for item_id in items[room_id]:
                if item_id not in items:
                    raise WorldError(f"Item '{item_id}' appears in room '{room_id}' but not in world items")
                room.items.append(item_id)

    return World(start, room_map, items)

@dataclass
class Game:
    world: World
    room_id: Optional[str] = None
    inventory: List[str] = field(default_factory=list)
    moves: int = 0

    def items_in(self, room_id: Optional[str] = None) -> List[str]:
        if room_id is None:
            return []
        if room_id not in self.world.rooms:
            return []
        return self.world.rooms[room_id].items.copy()

    def do(self, line: str) -> str:
        if not line.strip():
            raise ValueError("Empty command")

        try:
            command = parse(line)
        except ParseError as e:
            return str(e)

        verb, arg = command
        room = self.room_id if self.room_id else self.world.start

        if verb == "go":
            return self._go(arg)
        elif verb == "take":
            return self._take(arg)
        elif verb == "drop":
            return self._drop(arg)
        elif verb == "look":
            return self._look(arg)
        elif verb == "inventory":
            return self._inventory()
        else:
            # Fallback for any unrecognized verb
            return f"I don't understand that."

    def _go(self, arg: str) -> str:
        dir_name = arg.lower()
        if dir_name in DIRECTIONS:
            next_room_id = self.world.rooms[arg_name][dir_name]
            self.room_id = next_room_id
            self.moves += 1
            return self.do(self.look())
        else:
            return f"You can't go that way."

    def _take(self, arg: str) -> str:
        # Remove articles 'the', 'a', 'an' from arg
        clean_arg = arg
        for char in 'thean':
            clean_arg = clean_arg.replace(char, "")

        if not clean_arg:
            return "Take what?"

        # Find matching item
        found = False
        item_name = clean_arg

        # Check room first
        room_items = self.items_in(self.room_id)
        for item_id in room_items:
            item = self.world.items[item_id]
            if item.id == item_name or item.name.lower() == item_name:
                found = True
                if not item.portable:
                    return f"You can't take the {item.name}."
                self.inventory.append(item_id)
                return f"Taken: {item.name}."
        return f"You see no {item_name} here."

    def _drop(self, arg: str) -> str:
        # Remove articles
        clean_arg = arg
        for char in 'thean':
            clean_arg = clean_arg.replace(char, "")

        if not clean_arg:
            return "Drop what?"

        # Find matching item in inventory
        item_name = clean_arg

        for item_id in self.inventory:
            item = self.world.items[item_id]
            if item.id == item_name or item.name.lower() == item_name:
                return f"Dropped: {item.name}."
        return f"You aren't carrying that."

    def _look(self, arg: str) -> str:
        # Remove articles
        clean_arg = arg
        for char in 'thean':
            clean_arg = clean_arg.replace(char, "")

        if not clean_arg:
            return self.world.rooms[self.room_id].description

        # Search room items
        room_items = self.items_in(self.room_id)
        room_items.extend(self.inventory)

        found = False
        for item_id in room_items:
            item = self.world.items[item_id]
            if item.id == clean_arg or item.name.lower() == clean_arg:
                found = True
                break

        if found:
            return f"You see {item.name}."
        return f"You see no {clean_arg} here."

    def _inventory(self) -> str:
        names = []
        for item_id in self.inventory:
            item = self.world.items[item_id]
            names.append(item.name)

        if not names:
            return "You are carrying nothing."

        return f"You are carrying: {', '.join(names)}."

