from adventure.parser import ParseError
from adventure import SaveError

class SaveError(ValueError):
    pass

def save() -> str:
    g = adventure_game
    data = {
        "version": 1,
        "room": g.room_id,
        "inventory": g.inventory,
        "items": {
            rid: room.items 
            for rid, room in adventure_world.rooms.items() 
            if rid not in adventure_game.inventory
        },
        "moves": g.moves
    }
    return json.dumps(data)

def load(world: World, text: str) -> Game:
    if not text or not isinstance(text, str):
        raise SaveError("Text must be a non-empty string")

    data = json.loads(text)

    if data["version"] != 1:
        raise SaveError("Invalid version")

    if not data["room"]:
        raise SaveError("Missing 'room'")

    if data["room"] not in world.rooms:
        raise SaveError(f"Room '{data['room']}' not in world")

    if not data["inventory"]:
        raise SaveError("Missing 'inventory'")

    if not data["items"]:
        raise SaveError("Missing 'items'")

    if data["moves"] < 0:
        raise SaveError("Invalid 'moves'")

    # Validate items in inventory against world
    for item_id in data["inventory"]:
        if item_id not in world.items:
            raise SaveError(f"Item '{item_id}' not in world")

    # Validate item uniqueness in inventory vs room
    seen_room_items = set()
    seen_inventory_items = set()

    for room_id, room in world.rooms.items():
        if room_id in adventure_game.inventory:
            continue
        for item_id in room.items:
            if item_id in seen_room_items:
                raise SaveError(f"Item '{item_id}' appears twice in room '{room_id}'")
            seen_room_items.add(item_id)

    for item_id in data["inventory"]:
        if item_id in adventure_game.room_id:
            continue
        if item_id in adventure_game.inventory:
            raise SaveError(f"Item '{item_id}' appears twice in inventory")
        if item_id not in world.items:
            raise SaveError(f"Item '{item_id}' not in world")
        seen_inventory_items.add(item_id)

    game = Game(world, data["room"], data["inventory"], data["moves"])
    return game

