from dataclasses import dataclass
from typing import Tuple
import re

@dataclass
class Command:
    verb: str
    arg: str

class ParseError(ValueError):
    pass

def parse(line: str) -> Command:
    line = line.lower()

    # Split on whitespace
    parts = line.split()

    if not parts:
        raise ParseError("Empty or all-whitespace line")

    first_word = parts[0]

    # Check for 'go'
    if first_word == "go":
        if len(parts) < 2:
            raise ParseError("Go where?")
        if parts[1] not in DIRECTIONS:
            raise ParseError(f"'{parts[1].strip()} is not a direction.")
        return Command("go", parts[1])

    # Check for 'inventory', 'inv', 'i'
    if first_word in ("inventory", "inv", "i"):
        if len(parts) < 2:
            raise ParseError("I don't understand that.")
        return Command("inventory", parts[1])

    # Check for 'look', 'l', 'look at', 'examine', 'x'
    if first_word == "look" or first_word == "l":
        if len(parts) == 2:
            if parts[1] in DIRECTIONS:
                raise ParseError(f"Go where?")
            return Command("look", parts[1])
        elif len(parts) == 3:
            if parts[1] in DIRECTIONS:
                raise ParseError(f"Go where?")
            if parts[2].lower() in ("at", "examine"):
                return Command("look", parts[2])
        else:
            raise ParseError("I don't understand that.")

    # Check for 'take', 'get', 'drop', 'examine', 'x'
    if first_word in ("take", "get"):
        if len(parts) < 2:
            raise ParseError("Take what?")
        if parts[1] not in DIRECTIONS:
            raise ParseError(f"'{parts[1].strip()} is not a direction.")
        return Command("take", parts[1])
    elif first_word == "drop":
        if len(parts) < 2:
            raise ParseError("Drop what?")
        if parts[1] not in DIRECTIONS:
            raise ParseError(f"'{parts[1].strip()} is not a direction.")
        return Command("drop", parts[1])
    elif first_word == "examine":
        if len(parts) < 2:
            raise ParseError("Examine what?")
        if parts[1] not in DIRECTIONS:
            raise ParseError(f"'{parts[1].strip()} is not a direction.")
        return Command("examine", parts[1])
    elif first_word == "x":
        if len(parts) < 2:
            raise ParseError("Examine what?")
        if parts[1] not in DIRECTIONS:
            raise ParseError(f"'{parts[1].strip()} is not a direction.")
        return Command("x", parts[1])

    # Check for 'a' or 'an' removal
    for char in 'thean':
        if char in line:
            line = line.replace(char, "")

    if len(parts) < 2:
        raise ParseError("Take what?")

    return Command(first_word, " ".join(parts))
