                if item_id not in items:
                    raise WorldError(f"Item '{item_id}' appears in room '{room_id}' but not in world items")
                room.items.append(item_id)

    return World(start, room_map, items)

@dataclass
class Game:
    world: World
    room_id: Optional[str] = None
    inventory: List[str] = field(default_factory=list)
    moves: int = 0
    score: int = 0

    def items_in(self, room_id: Optional[str] = None) -> List[str]:
        if room_id is None:
            return []
        if room_id not in self.world.rooms:
            return []
        return self.world.rooms[room_id].items.copy()

    def locked_exits(self, room_id: Optional[str] = None) -> Set[str]:
        if room_id is None:
            return set()
        if room_id not in self.world.rooms:
            return set()
        return set(self.world.rooms[room_id].locks.keys())

    def do(self, line: str) -> str:
        if not line.strip():
            raise ValueError("Empty command")

        try:
            command = parse(line)
        except ParseError as e:
            return str(e)

        verb, arg = command

        if verb == "go":
            return self._go(arg)
        elif verb == "use":
            return self._use(arg)
        elif verb == "score":
            return self._score()
        elif verb == "look":
            return self._look(arg)
        elif verb == "inventory":
            return self._inventory()
        else:
            return f"I don't understand that."

    def _go(self, arg: str) -> str:
        dir_name = arg.lower()
        if dir_name in DIRECTIONS:
            next_room_id = self.world.rooms[arg_name][dir_name]["to"]
            self.room_id = next_room_id
            self.moves += 1
            return self.do(self.look())
        else:
            return f"The way {arg_name} is locked."

    def _use(self, arg: str) -> str:
        # Remove articles 'the', 'a', 'an' from arg
        clean_arg = arg
        for char in 'thean':
            clean_arg = clean_arg.replace(char, "")

        if not clean_arg:
            return "Use what?"

        # Find matching item
        found = False
        item_name = clean_arg

        # Check inventory first
        if item_name in self.inventory:
            for room_id in self.world.rooms.keys():
                if item_name in self.world.rooms[room_id].locks:
                    unlocked_dirs = []
                    for dir_str in DIRECTIONS:
                        if dir_str in self.world.rooms[room_id].locks:
                            unlocked_dirs.append(dir_str)
                    return f"Unlocked: {', '.join(unlocked_dirs)}."
            return f"You aren't carrying that."

        # Check room items
        room_items = self.items_in(self.room_id)
        room_items.extend(self.inventory)

        for item_id in room_items:
            item = self.world.items[item_id]
            if item.id == item_name or item.name.lower() == item_name:
                found = True
                break

        if not found:
            return f"You aren't carrying that."

        return f"Nothing here to use the {item_name} on."

    def _score(self) -> str:
        if self.score > 0:
            return f"You already have the score."

        if self.room_id == self.world.start:
            return "Your score is 0."

        first_visit = True
        for room_id, room in self.world.rooms.items():
            if room_id not in self.visited_rooms:
                if first_visit:
                    self.visited_rooms.add(room_id)
                    self.score += 10
                    self.visited_rooms = sorted(self.visited_rooms)
                    self.scored_items.clear()
                    first_visit = False
                else:
                    self.visited_rooms = sorted(self.visited_rooms)
                    self.scored_items.clear()

            # Check item taking
            for item_id in room.items:
                if item_id in self.inventory:
                    if item_id in self.scored_items:
                        continue
                    item = self.world.items[item_id]
                    if item.treasure > 0:
                        self.score += item.treasure
                        self.scored_items.add(item_id)
                        self.scored_items = sorted(self.scored_items)
                        break
            # Check item dropping
            for item_id in room.items:
                if item_id in self.inventory:
                    continue
                item = self.world.items[item_id]
                if item.treasure > 0:
                    self.score += item.treasure
                    self.scored_items.add(item_id)
                    self.scored_items = sorted(self.scored_items)
                    break

        return f"Your score is {self.score}."

    def _look(self, arg: str) -> str:
        # Remove articles
        clean_arg = arg
        for char in 'thean':
            clean_arg = clean_arg.replace(char, "")

        if not clean_arg:
            return self.world.rooms[self.room_id].description

        # Search room items
        room_items = self.items_in(self.room_id)
        room_items.extend(self.inventory)

        found = False
        for item_id in room_items:
            item = self.world.items[item_id]
            if item.id == clean_arg or item.name.lower() == clean_arg:
                found = True
                break

        if found:
            return f"You see {item.name}."
        return f"You see no {clean_arg} here."

    def _inventory(self) -> str:
        names = []
        for item_id in self.inventory:
            item = self.world.items[item_id]
            names.append(item.name)

        if not names:
            return "You are carrying nothing."

        return f"You are carrying: {', '.join(names)}."

