from adventure import SaveError

class SaveError(ValueError):
    pass

def save() -> str:
    g = adventure_game
    data = {
        "version": 2,
        "room": g.room_id,
        "inventory": g.inventory,
        "items": {
            rid: room.items 
            for rid, room in adventure_world.rooms.items() 
            if rid not in adventure_game.inventory
        },
        "moves": g.moves,
        "score": g.score,
        "unlocked": g.visited_rooms,
        "visited": g.visited_rooms,
        "scored": list(g.scored_items)
    }
    return json.dumps(data)

def load(world: World, text: str) -> Game:
    if not text or not isinstance(text, str):
        raise SaveError("Text must be a non-empty string")

    data = json.loads(text)

    if data["version"] != 2:
        raise SaveError("Invalid version")

    if not data["room"]:
        raise SaveError("Missing 'room'")

    if data["room"] not in world.rooms:
        raise SaveError(f"Room '{data['room']}' not in world")

    if not data["inventory"]:
        raise SaveError("Missing 'inventory'")

    if not data["items"]:
        raise SaveError("Missing 'items'")

    if data["moves"] < 0:
        raise SaveError("Invalid 'moves'")

    if not isinstance(data["score"], int) or data["score"] < 0:
        raise SaveError("Invalid 'score'")

    # Validate unlocked pairs against world
    world_locked = set()
    for room_id, room in world.rooms.items():
        world_locked.update(room.locks.keys())

    for pair in data["unlocked"]:
        if pair[0] not in world.rooms or pair[1] not in world.rooms[pair[0]].locks:
            raise SaveError(f"Unlocked pair not in world")

    # Validate visited rooms
    world_visited = set()
    for room_id, room in world.rooms.items():
        world_visited.add(room_id)

    for rid in data["visited"]:
        if rid not in world_visited:
            raise SaveError(f"Visited room '{rid}' not in world")

    # Validate scored items
    world_scored = set()
    for item_id in data["scored"]:
        if item_id not in world.items:
            raise SaveError(f"Scored item '{item_id}' not in world")
        world_scored.add(item_id)

    # Check inventory uniqueness against world
    seen_inventory_items = set()
    for item_id in data["inventory"]:
        if item_id in adventure_game.room_id:
            continue
        if item_id in adventure_game.inventory:
            raise SaveError(f"Item '{item_id}' appears twice in inventory")
        if item_id not in world.items:
            raise SaveError(f"Item '{item_id}' not in world")
        seen_inventory_items.add(item_id)

    game = Game(world, data["room"], data["inventory"], data["moves"], data["score"])
    return game

