### vfs/paths.py
This module handles path normalization, joining, splitting, and containment checks.

```python
import os
import fnmatch

class FSError(Exception):
    """Base error class for filesystem operations."""
    def __init__(self, path):
        self.path = normalize(path)
        super().__init__(f"error: {self.path}")

class NotADirectory(FSError):
    def __init__(self, path):
        super().__init__(path)

class AlreadyExists(FSError):
    def __init__(self, path):
        super().__init__(path)

class NotFound(FSError):
    def __init__(self, path):
        super().__init__(path)

class IsADirectory(FSError):
    def __init__(self, path):
        super().__init__(path)

class InvalidOperation(FSError):
    def __init__(self, path):
        super().__init__(path)

def normalize(path, cwd='/'):
    """
    Normalize a path.
    Returns an absolute path with no '.', '..', repeated '/', or trailing '/' (except root).
    Relative paths are taken relative to cwd.
    Raises ValueError if path is empty.
    """
    if not path:
        raise ValueError("path cannot be empty")

    # Normalize the input path
    norm_path = os.path.normpath(path)

    # Split into parts
    parts = norm_path.split('/')

    # Reconstruct path
    result = []
    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if not result:
                # If at root, stay at root
                continue
            else:
                result.pop()
        else:
            result.append(part)

    path = '/'.join(result)
    # Ensure absolute, no trailing slash (except root)
    if not path.startswith('/'):
        path = '/' + path
    if path != '/' and path.endswith('/'):
        path = path.rstrip('/')
    return path

def join(base, *parts):
    """
    Join paths like posixpath.join.
    A part starting with / starts over.
    Returns a normalized absolute path.
    """
    if not parts:
        return base
    if base:
        base = os.path.normpath(base)
    return os.path.normpath(os.path.join(base, *parts))

def split(path):
    """
    Split an absolute normalized path into (parent, name).
    Returns ('/', '') for root.
    """
    parts = path.split('/')
    if not parts or parts[0] == '/':
        return '/', ''
    else:
        return '/'.join(parts[:-1]), parts[-1]

def is_within(path, ancestor):
    """
    Tells whether the normalised path is the ancestor itself or lies below it.
    Example: '/ab' is not within '/a'.
    """
    norm_path = normalize(path)
    norm_ancestor = normalize(ancestor)
    return norm_path == norm_ancestor or norm_path.startswith(norm_ancestor + '/')
