```python
from .paths import (
    normalize,
    join,
    split,
    is_within,
    FSError,
    NotADirectory,
    AlreadyExists,
    NotFound,
    IsADirectory,
    InvalidOperation,
)

class FileSystem:
    def __init__(self):
        self._root = {}  # { normalized_path: ... }
        self._current = normalize("/")

    def pwd(self):
        """Return the current directory."""
        return normalize(self._current)

    def cd(self, path):
        """Change directory. Raises error if path not found or not a directory."""
        norm_path = normalize(path)

        if not is_within(norm_path, self._current):
            raise NotFound(norm_path)

        if norm_path in self._root and os.path.isfile(norm_path):
            raise NotADirectory(norm_path)

        old_path = self._current
        self._current = norm_path

        if norm_path in self._root:
            del self._root[old_path]

        self._root[norm_path] = {}

        # If changing to root, remove old root
        if self._current == '/':
            if self._root:
                del self._root[old_path]

    def mkdir(self, path, parents=False):
        """
        Create a directory. If parents, create missing parents too.
        If path exists, only raise error if it is a file.
        """
        if parents:
            norm_path = normalize(path)
            # Check existence relative to current if needed for parent creation,
            # but strictly, mkdir creates parents relative to current.
            # However, standard behavior for mkdir with parents is:
            # 1. Create path itself (if not exists).
            # 2. Create all parents of path.

            # For simplicity and standardism:
            # 1. Check if parent is missing.
            # 2. Create path itself.

            # Let's implement: Create all parents up to the target, then the target.
            parent_parts = split(path)[:-1]
            target_parts = split(path)

            # Create parent chain
            if not parent_parts:
                if target_parts[0] != '/':
                    raise NotFound(path)
                return

            current = self._current
            for p in parent_parts:
                norm_p = normalize(p)
                if not is_within(norm_p, current):
                    raise NotFound(norm_p)
                if norm_p in self._root:
                    # Already exists, check if file
                    if os.path.isfile(norm_p):
                        raise AlreadyExists(norm_p)
                    self._root[norm_p] = {}
                current = norm_p

            # Now create the target
            norm_target = normalize(path)
            if norm_target in self._root:
                if os.path.isfile(norm_target):
                    raise AlreadyExists(norm_target)
                self._root[norm_target] = {}
            else:
                self._root[norm_target] = {}

        else:
            norm_path = normalize(path)
            if norm_path in self._root:
                if os.path.isfile(norm_path):
                    raise AlreadyExists(norm_path)
                self._root[norm_path] = {}

    def write(self, path, text, append=False):
        """
        Create or overwrite the file.
        If append, add to end.
        Raises error if path is a directory.
        """
        norm_path = normalize(path)

        if norm_path in self._root and os.path.isdir(norm_path):
            raise IsADirectory(norm_path)

        if not norm_path:
            raise NotFound(norm_path)

        # Check if parent exists
        parent_parts = split(path)[:-1]
        if not parent_parts:
            if not is_within(norm_path, self._current):
                raise NotFound(norm_path)
        else:
            current = self._current
            for p in parent_parts:
                norm_p = normalize(p)
                if not is_within(norm_p, current):
                    raise NotFound(norm_p)
                if norm_p in self._root:
                    if os.path.isfile(norm_p):
                        raise NotADirectory(norm_p)
                    self._root[norm_p] = {}
                current = norm_p

            norm_parent = normalize(split(path)[:-1])[0]
            if norm_parent in self._root:
                if os.path.isfile(norm_parent):
                    raise NotADirectory(norm_parent)
                self._root[norm_parent] = {}

        # Handle append vs overwrite logic
        # If append, we treat existing file as empty to write to end.
        # Actually, standard behavior:
        # If append is False (default), create or overwrite.
        # If append is True, create file, then append text.

        # First, ensure parent exists and file is empty
        # ... (same logic as rm logic for parent)

        # Get file content or create empty
        if norm_path in self._root:
            # Check if file exists
            if os.path.isfile(norm_path):
                # If append is False, overwrite
                self._root[norm_path] = text
            else:
                # If append is True, treat as empty file
                self._root[norm_path] = []
        else:
            # Create file
            self._root[norm_path] = []
            if append:
                self._root[norm_path].append(text)

    def read(self, path):
        """Return the file's text."""
        norm_path = normalize(path)

        if norm_path in self._root and os.path.isfile(norm_path):
            return self._root[norm_path]
        raise NotFound(norm_path)

    def ls(self, path='.'):
        """
        List entries.
        Directory: names sorted, followed by '/'.
        File: list of names.
        """
        norm_path = normalize(path)

        if norm_path in self._root and os.path.isdir(norm_path):
            # Sort names as strings
            names = sorted(self._root[norm_path].keys(), key=lambda x: x)
            return [norm_path + '/' + n for n in names]
        else:
            # Check if it's a file
            if norm_path in self._root:
                if os.path.isfile(norm_path):
                    return [norm_path]
                else:
                    return []
            return []

    def rm(self, path, recursive=False):
        """
        Remove a file or directory and everything in it.
        If recursive, remove everything in the path.
        Raises InvalidOperation if path is / or current dir or ancestor.
        Raises IsADirectory if it's a directory and not recursive.
        """
        if path == '/':
            raise InvalidOperation('/')

        norm_path = normalize(path)

        if not is_within(norm_path, self._current):
            raise NotFound(norm_path)

        if norm_path in self._root:
            if os.path.isfile(norm_path):
                # Check if inside current (if recursive is False)
                if not recursive and is_within(norm_path, self._current):
                    raise InvalidOperation(norm_path)
                self._root.pop(norm_path)
            else:
                # Directory
                if not recursive:
                    raise InvalidOperation(norm_path)

                # Check if inside current
                if is_within(norm_path, self._current):
                    raise InvalidOperation(norm_path)

                # Remove and descend
                if is_within(norm_path, self._current):
                    # Recursively clear
                    self._clear_recursive(norm_path)
                else:
                    # Move up
                    self._move_up(norm_path)
        else:
            raise NotFound(norm_path)

    def _clear_recursive(self, path):
        """Helper to clear a directory and all subdirectories/files."""
        norm_path = normalize(path)
        self._root.pop(norm_path)
        for child in list(self._root.keys()):
            self._clear_recursive(child)

    def _move_up(self, path):
        """Helper to move a directory up to its parent."""
        norm_path = normalize(path)
        parent_parts = split(path)[:-1]
        if not parent_parts:
            if norm_path == '/':
                self._current = '/'
                return
            self._current = '/'
            return

        current = self._current
        for p in parent_parts:
            norm_p = normalize(p)
            if not is_within(norm_p, current):
                raise NotFound(norm_p)
            if norm_p in self._root:
                self._root[norm_p] = {}
                current = norm_p
            else:
                current = norm_p

    def mv(self, src, dst):
        """
        Move or rename a file or directory.
        If dst is existing directory, target is dst/NAME (NAME=src's name).
        Else target is dst.
        Raises InvalidOperation if src is / or current dir or ancestor.
        Raises InvalidOperation if target is src itself or inside it.
        Raises AlreadyExists if target exists.
        Raises NotFound if target's parent is missing.
        """
        if src == '/':
            raise InvalidOperation('/')
        if is_within(src, self._current):
            raise InvalidOperation(src)
        if src == self._current:
            raise InvalidOperation(src)

        norm_src = normalize(src)
        norm_dst = normalize(dst)

        if is_within(norm_dst, self._current):
            # dst is an existing directory (relative to current)
            # Target is dst/NAME
            target = join(norm_dst, src)
            # Ensure target is normalized
            target = normalize(target)
        else:
            target = join(norm_dst, '')
            target = normalize(target)

        # Check if target is src or inside src
        if is_within(target, src):
            raise InvalidOperation(src)

        if target == src:
            raise InvalidOperation(src)

        if target in self._root and os.path.isfile(target):
            raise AlreadyExists(target)

        # Find parent of target to check if exists
        parent_parts = split(target)[:-1]
        if not parent_parts:
            if is_within(target, self._current):
                parent = '/'.join(parent_parts)
            else:
                # Root level
                parent = self._current
        else:
            current = self._current
            for p in parent_parts:
                norm_p = normalize(p)
                if not is_within(norm_p, current):
                    raise NotFound(norm_p)
                if norm_p in self._root:
                    current = norm_p
                else:
                    # Parent doesn't exist?
                    # According to spec: "if the target's parent is missing"
                    raise NotFound(target)

        # Perform move
        # If src is directory, clear it recursively
        if os.path.isdir(src):
            self._clear_recursive(src)
        self._clear_recursive(target)
        self._root.pop(src)
        self._root[target] = {}

    def find(self, path='.', pattern='*'):
        """
        Find absolute paths of everything below path matching pattern.
        Returns list of paths sorted as strings.
        For a file, return [its path] if matches, else [].
        """
        norm_path = normalize(path)

        if norm_path not in self._root:
            raise NotFound(norm_path)

        results = []
        for child in self._root[norm_path]:
            child_path = join(norm_path, child)
            if is_within(child_path, norm_path):
                if os.path.isfile(child_path):
                    if pattern == '*' or fnmatch.fnmatchcase(child_path, pattern):
                        results.append(child_path)
                elif fnmatch.fnmatchcase(child, pattern):
                    results.append(child)
        return sorted(results)

    def exists(self, path):
        return True if path in self._root else False

    def is_dir(self, path):
        return True if path in self._root and os.path.isdir(path) else False
