### vfs/shell.py
This module provides the Shell wrapper that executes commands against a FileSystem.

```python
import sys
import shlex
import io

class Shell:
    def __init__(self, fs=None):
        if fs is None:
            self.fs = FileSystem()
        else:
            self.fs = fs
            # Ensure state is reset if it exists (though not strictly required by spec, 
            # we just wrap it)
            pass

    def run(self, script):
        """
        Run a script file.
        Returns (output, status).
        If file not readable, prints error to stderr, exits 2.
        """
        try:
            with open(script, 'r', encoding='utf-8') as f:
                lines = f.readlines()
        except Exception as e:
            sys.stderr.write(f"error: cannot read script {script}: {e}\n")
            sys.exit(2)

        output = []
        status = 0

        for line_num, line in enumerate(lines, 1):
            line = line.strip()
            if not line or line.startswith('#'):
                continue

            parts = shlex.split(line)
            if not parts:
                continue

            command = parts[0]
            args = parts[1:]

            # Execute command
            cmd_output, cmd_status = self._execute_command(command, args)

            # Capture output
            if cmd_status == 0:
                # If command succeeded, capture stdout (what user sees)
                # If command failed (status != 0), user sees error message printed to stderr
                stdout = sys.stdout.getvalue() if cmd_status == 0 else ""
                if stdout:
                    output.append(stdout)
            else:
                # Command failed, print error line to stderr
                error_line = f"{line_num}: {command}: {type(cmd_exception).__name__}: {cmd_exception.path}\n"
                sys.stderr.write(error_line)
                # Do not add error line to output string, but status becomes 1
                # The spec says: "an FSError adds the line ... and the status is 1"
                # "an unknown command adds ... and the status is 2"
                # "wrong arguments ... add ... and the status is 2"
                status = 1

            status += cmd_status

        return output, status

    def _execute_command(self, command, args):
        """Execute a single command and return (output, status)."""
        if command == 'pwd':
            return self.fs.pwd(), 0

        if command == 'cd':
            # Handle -p (parents)
            parents = False
            if args and args[0] == '-p':
                parents = True
                args = args[1:]
            if not args:
                raise ValueError("cd requires a path")
            self.fs.cd(normalize(args[0])), 0

        elif command == 'mkdir':
            # Handle -p
            parents = False
            if args and args[0] == '-p':
                parents = True
                args = args[1:]

            if not args:
                raise ValueError("mkdir requires at least one path")

            # mkdir returns immediately (status 0)
            self.fs.mkdir(normalize(args[0]), parents), 0

        elif command == 'ls':
            if not args:
                raise ValueError("ls requires a path")
            self.fs.ls(normalize(args[0])), 0

        elif command == 'rm':
            # Handle -r
            recursive = False
            if args and args[0] == '-r':
                recursive = True
                args = args[1:]

            if not args:
                raise ValueError("rm requires a path")

            self.fs.rm(normalize(args[0]), recursive), 0

        elif command == 'mv':
            if len(args) < 2:
                raise ValueError("mv requires SRC DST")
            self.fs.mv(normalize(args[0]), normalize(args[1])), 0

