        # Actually, let's refine the char parsing loop.
        # If char is digit, continue number logic.
        # If char is dash, check if followed by digits.
        # If char is letter, it's a word.

        # Re-scan char-by-char logic is safer.
        if i >= len(source):
            break

        c = source[i]

        # Check if it's a digit
        if c.isdigit():
            num_str = ''
            while i < len(source) and source[i].isdigit():
                num_str += source[i]
                i += 1
            if num_str == '-':
                tokens.append(Token('-', '-', 0, 0))
                i += 1
                continue

            num_val = int(num_str)
            tokens.append(Token(str(num_val), num_val, 0, 0))
            i += 1 # Skip past digit sequence
            continue

        # Check if it's a dash
        if c == '-':
            i += 1
            if i < len(source) and source[i].isdigit():
                num_str = source[i:]
                if num_str:
                    val = int(num_str)
                    tokens.append(Token(str(val), val, 0, 0))
                    i += len(num_str)
                    continue
            # If standalone dash, it's a word.
            tokens.append(Token('-', '-', 0, 0))
            i += 1
            continue

        # It's a word (or newline)
        tokens.append(Token(None, source[i], 0, 0))
        i += 1
        continue

