from typing import NamedTuple, Iterable, Tuple, Optional, Any
from bisect import bisect_left

from .store import ObjectNotFound, AmbiguousPrefix, CorruptObject


@dataclass(frozen=True)
class Blob:
    data: bytes

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Blob):
            return NotImplemented
        return self.data == other.data

    def __hash__(self) -> int:
        return hash(self.data)


@dataclass(frozen=True)
class TreeEntry(NamedTuple):
    name: str
    kind: str
    oid: str

    @classmethod
    def from_str(cls, name: str, kind: str, oid: str) -> TreeEntry:
        return cls(name=name, kind=kind, oid=oid)

    @classmethod
    def from_line(cls, line: str) -> TreeEntry:
        parts = line.rstrip().split("\t")
        if len(parts) != 3:
            raise ValueError(f"Invalid tree entry line: {line!r}")
        return cls(name=parts[0], kind=parts[1], oid=parts[2])

    def __hash__(self) -> int:
        return hash((self.name, self.kind, self.oid))

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, TreeEntry):
            return NotImplemented
        return self.name == other.name and self.kind == other.kind and self.oid == other.oid


@dataclass(frozen=True)
class Tree(NamedTuple):
    entries: Tuple[TreeEntry, ...]
    oid: str

    def __init__(self, entries: Iterable[TreeEntry]):
        # Sort by UTF-8 bytes of name
        sorted_entries = sorted(entries, key=lambda e: e.name.encode("utf-8"))
        self.entries = tuple(sorted_entries)

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Tree):
            return NotImplemented
        return self.entries == other.entries and self.oid == other.oid

    def __hash__(self) -> int:
        return hash((self.entries, self.oid))


