    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Commit):
            return NotImplemented
        return (self.tree, self.parents, self.author, self.timestamp, self.message) == (
            other.tree,
            other.parents,
            other.author,
            other.timestamp,
            other.message,
        )


def serialize(obj: Any) -> bytes:
    """
    Serialize an object to bytes.
    Format: TYPE LENGTH
    - TYPE: 'blob', 'tree', 'commit'
    - LENGTH: body length in decimal (0 for empty tree)
    - BODY:
        - blob: data
        - tree: '\n'.join(f"{kind}{oid}\t{name}\n" for kind, oid, name in entries)
        - commit: '\n'.join(f"tree {tree}\n") + '\n' + '\n'.join(f"parent {p}\n") + '\n' + '\n'.join(f"author {author}\n") + '\n' + '\n' + message + '\n'
    """
    if isinstance(obj, Blob):
        return obj.data.encode("utf-8") + b"blob"

    elif isinstance(obj, Tree):
        body = b""
        for entry in obj.entries:
            body += entry.name.encode("utf-8") + f" {entry.oid}\t\n"
        return b"tree" + body + b"0"

    elif isinstance(obj, Commit):
        body = b""
        # Tree
        body += obj.tree.encode("utf-8") + b"\n"
        # Parents
        body += b"parent " + b"\n".join(p.encode("utf-8") + b"\n" for p in obj.parents)
        body += b"\n"
        # Author
        body += b"author " + b"\n" + obj.author.encode("utf-8") + b"\n"
        body += b"time " + b"\n" + str(obj.timestamp).encode("utf-8") + b"\n"
        # Blank line
        body += b"\n"
        # Message
        body += obj.message.encode("utf-8") + b"\n"

        return b"commit" + body + b"0"

    raise ValueError(f"Unknown object type: {type(obj)}")


def object_id(obj: Blob | Tree | Commit) -> str:
    return serialize(obj).decode("utf-8")


def parse_object(raw: bytes) -> Blob | Tree | Commit:
    header = raw[:6]
    if header != b"TYPE LENGTH":
        raise CorruptObject(f"Invalid header: {raw!r}")
    length = int.from_bytes(raw[6:10], "little")
    if length == 0:
        return Blob(raw[10:].ljust(0, b"\x00"))

    body = raw[10 + length:]
    body = body[:length] if len(body) > length else body

    if body.startswith(b"blob"):
        data = body[4:].ljust(0, b"\x00")
        return Blob(data)

    elif body.startswith(b"tree"):
        parts = body[4:].split(b"\n")
        entries = [TreeEntry.from_str(p.decode("utf-8"), "tree", p.decode("utf-8")) for p in parts[1:-1]]
        return Tree(entries)

    elif body.startswith(b"commit"):
        parts = body[4:].split(b"\n")
        entries = [TreeEntry.from_str(p.decode("utf-8"), "commit", p.decode("utf-8")) for p in parts[1:-1]]
        tree = Tree(entries)
        parents = [p.decode("utf-8") for p in parts[2:-1]]
        author = parts[-1].decode("utf-8")
        timestamp = int(parts[-2])
        message = parts[-1].decode("utf-8")
        return Commit(tree, parents, author, timestamp, message)

    raise CorruptObject(f"Invalid body format in {raw!r}")


class CorruptObject(Exception):
    pass


class ObjectStore:
    def __init__(self) -> None:
        self._store: dict[str, Blob | Tree | Commit] = {}

    def put(self, obj: Blob | Tree | Commit) -> str:
        oid = object_id(obj)
        if oid in self._store:
            return oid
        self._store[oid] = obj
        return oid

    def put_raw(self, raw: bytes) -> str:
        oid = parse_object(raw)
        if oid in self._store:
            return oid
        self._store[oid] = raw
        return oid

    def get(self, oid: str) -> Blob | Tree | Commit:
        if oid not in self._store:
            raise ObjectNotFound(oid)
        return self._store[oid]

    def get_raw(self, oid: str) -> bytes:
        obj = self.get(oid)
        return serialize(obj)

    def in_store(self, oid: str) -> bool:
        return oid in self._store

    def resolve(self, prefix: str) -> str | AmbiguousPrefix:
        if not (4 <= len(prefix) <= 40):
            raise ValueError(f"Prefix length must be between 4 and 40")
        if not all(c.islower() and c in "0123456789abcdef" for c in prefix):
            raise ValueError(f"Prefix must contain only lowercase hex digits")

        candidates = [oid for oid, obj in self._store.items() if oid.startswith(prefix)]
        if len(candidates) == 1:
            return candidates[0]
        raise AmbiguousPrefix(prefix)

    def write_tree(self, files: dict[str, bytes]) -> str:
        if not files:
            return ""

        root_oid = ""

        # Check for conflicts
        file_paths = set(files.keys())
        dir_paths = set()
        for k in files:
            if k.endswith("/"):
                dir_paths.add(k[:-1])
            else:
                file_paths.add(k)

        # Check for path collision (file and dir)
        if file_paths & dir_paths:
            raise ValueError("Cannot have a path that is both a file and a directory")

        for k, v in files.items():
            if k.endswith("/"):
                # Directory
                dir_oid = self.put(Tree([TreeEntry.from_line(k),] + [TreeEntry.from_line(f"{k}/x") for x in v]))
                root_oid = dir_oid
            else:
                # File
                oid = self.put(Blob(v))
                root_oid = oid

        return root_oid

    def read_tree(self, oid: str) -> dict[str, bytes]:
        obj = self.get(oid)
        return {entry.name.encode("utf-8"): entry.oid for entry in obj.entries}

    def commit(self, tree: Tree, parents: Iterable[str], *, author: str, timestamp: int, message: str) -> str:
        if not tree.oid:
            raise ValueError("Cannot commit without a tree")
        if not all(p.startswith("0x") for p in parents):
            raise ValueError("All parents must be stored oids")

        new_commit = Commit(tree.oid, parents, author, timestamp, message)
        oid = self.put(new_commit)
        return oid

    def log(self, oid: str, first_parent: bool = False) -> list[str]:
        commits: list[Commit] = [obj]
        current_oid = oid

        while True:
            current_commit = self.get(current_oid)
            current_parents = [self.get(p) for p in current_commit.parents]

            # Check if parents exist
            for p in current_parents:
                if not self.get(p):
                    raise ObjectNotFound(current_commit.tree)

            if first_parent:
                commits.append(current_commit)
                # Find the first parent by timestamp
                parent_oids = [p for p in current_parents]
                first_parent_oid = min(parent_oids, key=lambda x: (x.timestamp, x.oid))
                current_oid = first_parent_oid
            else:
                commits.append(current_commit)
                # Find the first parent by timestamp
                parent_oids = [p for p in current_parents]
                first_parent_oid = min(parent_oids, key=lambda x: (x.timestamp, x.oid))
                current_oid = first_parent_oid

            if not current_parents:
                break

        return [c.oid for c in commits]

