```python
from __future__ import annotations

from .objects import Blob, Tree, TreeEntry
from .store import ObjectNotFound, AmbiguousPrefix, Change


def diff_trees(store: object, old: str | None, new: str | None) -> list[Change]:
    if old is None and new is None:
        return []
    if old is None:
        return diff_commits(store, None, new)

    if new is None:
        return diff_commits(store, old, None)

    old_tree = store.get(old)
    new_tree = store.get(new)

    if old_tree is None or new_tree is None:
        # Handle case where one is missing (should be caught by parent check in commit)
        # But if a file is missing, it's a deletion
        # If a tree is missing, it's empty
        if new is not None:
            return diff_commits(store, old, new)
        return diff_trees(store, old, None)

    # Check for subtree equality
    old_entries = {entry.name.encode("utf-8"): entry for entry in old_tree.entries}
    new_entries = {entry.name.encode("utf-8"): entry for entry in new_tree.entries}

    # Filter out entries that are identical
    filtered_old = {k: v for k, v in old_entries.items() if k in new_entries and v == new_entries[k]}
    filtered_new = {k: v for k, v in new_entries.items() if k in old_entries and v == old_entries[k]}

    # Determine remaining changes based on set difference
    old_paths = set(old_entries.keys())
    new_paths = set(filtered_new.keys())

    changes: list[Change] = []

    # Files present in both but different
    for path, new_blob in filtered_new.items():
        if path not in old_paths:
            changes.append(Change("D", path, old_paths, new_blob))
        else:
            old_blob = old_entries[path]
            if new_blob != old_blob:
                changes.append(Change("M", path, old_blob, new_blob))

    # Files present in new but not in old (deletions)
    for path in new_paths - old_paths:
        changes.append(Change("D", path, old_paths, None))

    # Files in old but not in new (deletions)
    for path in old_paths - new_paths:
        changes.append(Change("D", path, new_paths, None))

    # Files in new but not in old (adds)
    for path in new_paths:
        changes.append(Change("A", path, None, new_paths))

    # Sort by path
    changes.sort(key=lambda c: c.path)
    return changes


def diff_commits(store: object, old: str | None, new: str | None) -> list[Change]:
    if old is None and new is None:
        return []
    if old is None:
        return diff_trees(store, None, new)
    if new is None:
        return diff_trees(store, old, None)

    old_commit = store.get(old)
    new_commit = store.get(new)

    if old_commit is None or new_commit is None:
        raise ObjectNotFound(old) if old else ObjectNotFound(new)

    return diff_trees(store, old, new)


def format_changes(changes: list[Change]) -> str:
    lines = [f"{c.status}\t{c.path}\n" for c in changes]
    return "".join(lines)
