from dataclasses import dataclass, field
from decimal import Decimal, ROUND_DOWN
from typing import Dict, Optional, Set

# Frozen dataclasses
@dataclass(frozen=True)
class Equal:
    members: Optional[Set[str]] = field(default_factory=set)

    def get_share(self, group: "Group") -> int:
        if self.members:
            return 0
        return group.members_to_group() // self.members

    def get_share_str(self, group: "Group") -> str:
        return str(self.get_share(group))

    def __repr__(self):
        return f"Equal(members={self.members})"

@dataclass(frozen=True)
class Exact:
    shares: Dict[str, int] = field(default_factory=dict)

    def get_share(self, group: "Group") -> int:
        if self.members:
            return self.get_share_str()
        return self.get_share_str()

    def __repr__(self):
        return f"Exact(shares={self.shares})"

@dataclass(frozen=True)
class Percent:
    shares: Dict[str, Decimal] = field(default_factory=dict)

    def get_share(self, group: "Group") -> int:
        if self.members:
            return self.get_share_str()
        return self.get_share_str()

    def __repr__(self):
        return f"Percent(shares={self.shares})"

@dataclass(frozen=True)
class Expense:
    description: str
    paid_by: str
    amount: int
    split: Equal | Exact | Percent

    def __repr__(self):
        return f"Expense({self.description}, paid_by={self.paid_by}, {self.split})"

@dataclass(frozen=True)
class Group:
    members: List[str]
    expenses: List[Expense] = field(default_factory=list)
    payments: List[tuple] = field(default_factory=list)

    @property
    def members_to_group(self) -> Set[str]:
        return set(self.members)

    def __len__(self) -> int:
        return len(self.members)

    def __repr__(self):
        return f"Group({self.members})"

    def add_member(self, name: str) -> None:
        if name in self.members:
            raise ValueError(f"Member {name} already exists in group")
        self.members.append(name)

    def add_expense(self, expense: Expense) -> Dict[str, int]:
        shares: Dict[str, int] = {}
        for name in self.members:
            shares[name] = expense.get_share(self)
        return shares

    def add_payment(self, payer: str, payee: str, amount: int) -> None:
        if payer not in self.members:
            raise ValueError(f"Payer {payer} not in group members")
        if payee not in self.members:
            raise ValueError(f"Payee {payee} not in group members")
        self.payments.append((payer, payee, amount))

    @property
    def expenses(self) -> List[Expense]:
        return self.expenses

    @property
    def payments(self) -> List[tuple]:
        return self.payments
