from decimal import Decimal

from split.model import Group

def balances(group: Group) -> Dict[str, int]:
    """
    Returns a dict from every member (alphabetical order) to their balance in cents.
    Positive means the group owes them money.
    """
    balances = {}
    for name in sorted(group.members):
        balance = 0
        for expense in group.expenses:
            balance -= expense.get_share(group)
        for payment, _ in group.payments:
            if name == payment[0]:
                balance -= payment[2]  # paid out
            elif name == payment[1]:
                balance += payment[2]  # paid in
        balances[name] = balance
    return balances

def format_balances(bals: Dict[str, int]) -> str:
    result = []
    for name in sorted(bals.keys()):
        amount = bals[name]
        if amount > 0:
            amount_str = format_amount(amount)
            result.append(f"+{amount_str}")
        elif amount < 0:
            amount_str = format_amount(amount)
            result.append(f"-{amount_str}")
        else:
            amount_str = format_amount(amount)
            result.append(f"{amount_str}")
    return "\n".join(result)
