from decimal import Decimal

from split.model import Group
from split.balances import balances, format_balances

def _transfer(creditor: str, debtor: str, amount: int) -> None:
    from split.model import Transfer
    Transfer(payer=debtor, payee=creditor, amount=amount)

def settle(bals: Dict[str, int]) -> None:
    """
    Greedily settle debts until all balances are zero.
    Takes balances dict (not modified).
    """
    while True:
        creditors = [name for name, bal in bals.items() if bal > 0]
        debtors = [name for name, bal in bals.items() if bal < 0]

        if not creditors or not debtors:
            break

        cred_max = max(creds, key=lambda x: bals[x])
        deb_max = max(debs, key=lambda x: bals[x])

        if cred_max == deb_max:
            cred, deb = cred_max, deb_max

        amount = min(abs(bals[cred_max]), abs(bals[deb_max]))
        _transfer(cred_max, deb_max, amount)

        for name in creditors:
            bals[name] -= amount
        for name in debtors:
            bals[name] += amount

def format_plan(transfers: List) -> str:
    if not transfers:
        return "All settled.\n"
    result = []
    for transfer in transfers:
        amount_str = format_amount(transfer.amount)
        result.append(f"{transfer.payer} pays {transfer.payee} {amount_str}")
    return "\n".join(result)
